/* UEPA — Processo Seletivo Unificado para Residência Médica, Grupo A (Acesso Direto). Cadernos e gabaritos oficiais definitivos. */
window.TRYCKTRACK_QUESTION_BANK = (window.TRYCKTRACK_QUESTION_BANK || []).concat([{"id":"uepa-2026-001","number":1,"area":"Otorrinolaringologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente de 75 anos, vem a UBS pois vem apresentando quadro de zumbido em ouvido esquerdo, redução da audição do mesmo ouvido, relata uso diário de hastes de algodão (cotonetes) para higiene. Após otoscopia observa rolha de cera, sem ver membrana timpânica. Neste caso o tratamento instituído deve ser:","options":{"A":"iniciar lavagem auricular guiada por otoscópio na APS.","B":"indicar solução otológica cerolitica por cinco dias e reavaliar em sete dias.","C":"encaminhar ao otorrino para avaliação e manejo adequado.","D":"orientar suspensão do uso de hastes de algodão e reavaliar após trinta dias.","E":"orientações sobre a hipoacusia fisiológica do envelhecimento."},"answer":"B","assunto":"Audiologia","topico":"Patologias Auditivas"},{"id":"uepa-2026-002","number":2,"area":"Cardiologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Em atendimento na UBS, você avalia homem de 59 anos, hipertenso há seis anos, sem lesão de órgão alvo e exames todos normais para investigar hipertensão secundária. Em uso de losartana 50 mg 2x dia, hidroclorotiazida 50 mg 1x pela manhã, anlodipino 10 mg pela manhã, sinvastatina 40 mg pela noite, trazendo MRPA com pressão média 155 por 95 mmHg. O manejo adequado para controle da pressão arterial, neste caso é:","options":{"A":"iniciar espironolactona associada as drogas já instituídas.","B":"substituir anlodipino por um betabloqueador.","C":"encaminhar ao cardiologista para avaliação e manejo.","D":"substituir hidroclorotiazida por espironolactona e reavaliar em três meses.","E":"iniciar AAS como medida de prevenção secundaria otimizando estatina."},"answer":"A","assunto":"Hipertensão Arterial Sistêmica (HAS)","topico":"Tratamento da Hipertensão arterial"},{"id":"uepa-2026-003","number":3,"area":"Neurologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Idosa de 75 anos vem acompanhada dos filhos na UBS para consulta, paciente HAS e DM sem outras comorbidades, apresenta quadro de esquecimento, rigidez muscular, relatando que está vendo pessoas que não estão lá e sentindo aranhas nos braços iniciado gradualmente há seis meses. A conduta a ser instituída neste caso é:","options":{"A":"iniciar lítio dose gradual.","B":"solicitar hemograma e VHS/PCR.","C":"iniciar haloperidol gotas VO.","D":"solicitar parecer da psicologia.","E":"encaminhar ao neurologista."},"answer":"E","assunto":"Demências","topico":"Demência com Corpos de Lewy"},{"id":"uepa-2026-004","number":4,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Ao participar de um treinamento sobre testes rápidos para Tuberculose em crianças, foi dito que o poder de acurácia de um teste era alto, quando:","options":{"A":"a probabilidade de um teste dar um resultado negativo para pessoas que não possuem a doença ou condição em questão.","B":"a capacidade do teste de identificar corretamente indivíduos que possuem a condição de interesse, ou seja, a probabilidade de um resultado positivo dado que a pessoa está doente.","C":"a probabilidade ou condição de um item, pessoa ou sistema antes de uma intervenção, avaliação ou teste, servindo como linha de base para medir mudanças futuras.","D":"a proporção total de acertos, verdadeiros positivos e verdadeiros negativos, em relação a todos os indivíduos testados.","E":"a probabilidade de um resultado positivo ser verdadeiro, indicando a chance de um indivíduo realmente ter a doença ou condição."},"answer":"D","assunto":"Epidemiologia","topico":"Testes Diagnósticos","subtopico":"Medidas de Desempenho de Testes Diagnósticos (ou Medidas de Performance de Testes Diagnósticos)"},{"id":"uepa-2026-005","number":5,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Você está utilizando USG para diagnostico de estenose de carótidas em 1.000 idosos com hipertensão arterial, como forma de prevenção de AVEi. Considerando que a sensibilidade e a especificidade da técnica do USG utilizado é de 90% e que a incidência de estenose de carótida nesta população é de 20%. O valor preditivo positivo desta técnica por USG para avaliar carótidas é de:","options":{"A":"6,92%","B":"69,2%","C":"692,0%","D":"0,6%","E":"0,06%"},"answer":"B","assunto":"Epidemiologia","topico":"Testes Diagnósticos","subtopico":"Medidas de Desempenho de Testes Diagnósticos (ou Medidas de Performance de Testes Diagnósticos)"},{"id":"uepa-2026-006","number":6,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Trabalhadores sazonais que residem em dois territórios solicitam vinculação a duas UBS para garantir acompanhamento. A conduta prevista pela PNAB, é:","options":{"A":"garantir vínculo único por usuário, sem possibilidade de cadastro em serviço adicional.","B":"permitir vinculação a mais de uma UBS/EAB quando necessário, assegurando continuidade do cuidado e acesso ampliado.","C":"autorizar duplo vínculo apenas para gestantes em seguimento específico de pré-natal.","D":"autorizar duplo vínculo exclusivamente para pessoas em cuidados paliativos domiciliares.","E":"condicionar duplo vínculo à determinação judicial, conforme pactuação municipal extraordinária."},"answer":"B","assunto":"Sistema Único de Saúde (SUS)","topico":"Atenção Primária à Saúde (APS) no Brasil","subtopico":"Política Nacional de Atenção Básica (PNAB)"},{"id":"uepa-2026-007","number":7,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A gestão cogita instalar seis equipes em uma única UBS para ampliar cobertura. O parâmetro que orienta essa decisão segundo a PNAB, é:","options":{"A":"autorizar qualquer número de equipes se houver espaço físico.","B":"recomendar no máximo duas equipes por UBS para evitar redundância.","C":"recomendar até quatro equipes por UBS para garantir potencial resolutivo.","D":"obrigar apenas uma equipe por UBS para fortalecer vínculo.","E":"definir número de equipes exclusivamente por decisão política local, sem parâmetros técnicos."},"answer":"C","assunto":"Sistema Único de Saúde (SUS)","topico":"Atenção Primária à Saúde (APS) no Brasil","subtopico":"Política Nacional de Atenção Básica (PNAB)"},{"id":"uepa-2026-008","number":8,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Encaminhamentos diretos para alta complexidade causam filas desordenadas e ociosidade na APS. Neste caso, a diretriz contrariada, é:","options":{"A":"Universalidade sem critérios clínicos.","B":"Hierarquização e regionalização com referência e contrarreferência.","C":"Equidade com priorização de vulneráveis.","D":"Complementaridade privada contratualizada.","E":"Participação social deliberativa."},"answer":"B","assunto":"Sistema Único de Saúde (SUS)","topico":"Processos de Descentralização e Regionalização do SUS","subtopico":"Regionalização do SUS"},{"id":"uepa-2026-009","number":9,"area":"Psiquiatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente de 40 anos com delírios persecutórios há 2 meses, sem alucinações auditivas, sem prejuízo grave no funcionamento. Neste caso o provável diagnóstico, é:","options":{"A":"Transtorno delirante","B":"Esquizofrenia","C":"Transtorno esquizoafetivo","D":"Transtorno psicótico breve","E":"Transtorno bipolar com sintomas psicóticos"},"answer":"A","assunto":"Transtorno Psicóticos","topico":"Transtorno Delirante Persistente"},{"id":"uepa-2026-010","number":10,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A equipe planeja quatro profissionais da mesma categoria, cada um com 12h semanais. De acordo com a PNAB, a alternativa correta, é:","options":{"A":"aceitar sem limite de número profissionais por categoria.","B":"aceitar cargas mínimas de 5h semanais por profissional, desde que a soma alcance 40h.","C":"respeitar máximo de 3 profissionais por categoria e mínimo de 10h semanais por profissional, mantendo 40h/equipe.","D":"permitir atuação sem vínculo, com plantões alternados cobrindo a equipe mínima.","E":"flexibilizar parâmetros mediante acordo interno da equipe, sem comunicação à gestão."},"answer":"C","assunto":"Sistema Único de Saúde (SUS)","topico":"Atenção Primária à Saúde (APS) no Brasil","subtopico":"Política Nacional de Atenção Básica (PNAB)"},{"id":"uepa-2026-011","number":11,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Em emergência sanitária, o gestor local remaneja recursos sem apreciação do Conselho de Saúde. O status jurídico desse colegiado, é:","options":{"A":"Órgão consultivo sem poder de decisão orçamentária vinculante.","B":"Instância independente sem interface com planejamento e finanças.","C":"Colegiado restrito à esfera nacional e conferências quadrienais.","D":"Comissão temporária acionada exclusivamente em crises epidêmicas.","E":"Órgão permanente e deliberativo, com função de controle social."},"answer":"E","assunto":"Sistema Único de Saúde (SUS)","topico":"Principais marcos legais do SUS","subtopico":"Leis orgânicas da saúde"},{"id":"uepa-2026-012","number":12,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Em um município, um usuário com condições crônicas circula entre UBS, ambulatório especializado e hospital sem integração de informações. Exames se repetem e não há retorno formal à equipe de origem. A gestão busca reorganizar o fluxo assistencial conforme o modelo das Redes de Atenção à Saúde. A conduta mais adequada para organizar esse cuidado, é:","options":{"A":"encaminhar o usuário diretamente para hospital de referência sem coordenação pela APS.","B":"manter o usuário vinculado à APS como coordenadora do cuidado, utilizando regulação para acesso aos demais serviços e garantindo contrarreferência.","C":"transferir o acompanhamento definitivo para o ambulatório especializado, encerrando o vínculo com a UBS.","D":"atuar apenas nos episódios de agudização clínica que resultem em internação hospitalar.","E":"orientar a busca por serviços privados para acelerar o acesso a consultas e exames."},"answer":"B","assunto":"Sistema Único de Saúde (SUS)","topico":"Processos de Descentralização e Regionalização do SUS","subtopico":"Regionalização do SUS"},{"id":"uepa-2026-013","number":13,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Uma coorte de 800 indivíduos foi acompanhada por 2 anos; ocorreram 40 casos do desfecho. Parte dos indivíduos foi perdida ao longo do seguimento. A medida mais adequada quando há tempos de observação distintos, é:","options":{"A":"Incidência acumulada","B":"Prevalência pontual","C":"Densidade de incidência (taxa)","D":"Razão de prevalência","E":"Proporção de atacados"},"answer":"C","assunto":"Epidemiologia","topico":"Medidas de saúde coletiva","subtopico":"Principais medidas de frequência de doenças"},{"id":"uepa-2026-014","number":14,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Em investigação epidemiológica no município, avaliou-se situação relacionada a ocorrência de doenças e aspectos metodológicos. Sobre o cenário descrito, assinale a alternativa correta.","options":{"A":"Apresenta conceito de razão de chances.","B":"Corresponde à densidade de incidência.","C":"Apresenta conceito de incidência.","D":"Refere-se à letalidade.","E":"Apresenta conceito de prevalência."},"answer":null,"assunto":"Epidemiologia","topico":"Medidas de saúde coletiva","subtopico":"Principais medidas de frequência de doenças","annulled":true},{"id":"uepa-2026-015","number":15,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Em uma área ribeirinha com difícil acesso e indicadores sociais desfavoráveis, a gestão municipal precisa reorganizar a cobertura dos Agentes Comunitários de Saúde (ACS). Qual estratégia está de acordo com a Política Nacional de Atenção Básica (PNAB)?","options":{"A":"Fixar um ACS para cerca de 1.200 pessoas, compensando distâncias com telemonitoramento estruturado e agendamento remoto.","B":"Adscrever apenas domicílios próximos à UBS, excluindo áreas remotas com baixa densidade e alto custo operacional.","C":"Assegurar cobertura total do território com teto de 750 pessoas por ACS, ajustando quantitativos por critérios epidemiológicos e sociais.","D":"Substituir ACS por equipe itinerante de especialidades, centralizando ações clínicas de maior complexidade.","E":"Alternar mensalmente os ACS por sorteio, redistribuindo microáreas para equilibrar a carga de trabalho."},"answer":"C","assunto":"Sistema Único de Saúde (SUS)","topico":"Atenção Primária à Saúde (APS) no Brasil","subtopico":"Política Nacional de Atenção Básica (PNAB)"},{"id":"uepa-2026-016","number":16,"area":"Psiquiatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Homem de 24 anos relata ataques súbitos de medo intenso, palpitações, sensação de morte iminente e esquiva de locais públicos. Ataques recorrentes há 3 meses. Qual diagnóstico?","options":{"A":"Transtorno de pânico","B":"Transtorno de ansiedade generalizada","C":"Transtorno obsessivo-compulsivo","D":"Transtorno de ansiedade social","E":"Transtorno de estresse pós-traumático"},"answer":"A","assunto":"Transtornos Ansiosos","topico":"Transtorno de Pânico"},{"id":"uepa-2026-017","number":17,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Durante surto de dengue, a CIB discute responsabilidades. Segundo a Lei nº 8.080/1990, compete aos estados:","options":{"A":"executar atenção básica diretamente em todos os municípios.","B":"coordenar redes regionais e apoiar municípios nas ações de vigilância.","C":"formular políticas nacionais de saúde.","D":"regular serviços privados em todo território nacional.","E":"definir percentuais constitucionais para financiamento."},"answer":"B","assunto":"Sistema Único de Saúde (SUS)","topico":"Principais marcos legais do SUS","subtopico":"Leis orgânicas da saúde"},{"id":"uepa-2026-018","number":18,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Em estudo caso-controle sobre câncer de pulmão, o odds ratio para tabagismo foi 4,0. Qual interpretação é adequada?","options":{"A":"Quatro vezes maior risco absoluto","B":"Quatro vezes mais chance de exposição","C":"Quatro vezes maior mortalidade","D":"Quatro vezes maior prevalência","E":"Quatro vezes mais chance de desenvolver câncer entre expostos"},"answer":"E","assunto":"Epidemiologia","topico":"Medidas de Associação e Medidas de Impacto","subtopico":"Odds Ratio ou Razão de Chances"},{"id":"uepa-2026-019","number":19,"area":"Psiquiatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A Reforma Psiquiátrica brasileira propõe a desinstitucionalização como eixo central da política de saúde mental. Contudo, a efetivação desse modelo depende da superação de obstáculos estruturais, financeiros e culturais. Considerando todas as dimensões analisadas, a alternativa que descreve, de forma mais completa, os principais desafios que ainda comprometem a plena implementação da desinstitucionalização no Brasil é:","options":{"A":"a escassez de leitos em hospitais psiquiátricos e a falta de profissionais de saúde mental nas regiões Norte e Nordeste, sem mencionar a necessidade de adequação legislativa.","B":"a resistência dos movimentos de usuários e familiares ao modelo comunitário, associada à ausência de protocolos clínicos padronizados para o CAPS.","C":"a insuficiência de recursos financeiros destinados aos serviços comunitários, a fragilidade da articulação entre CAPS e atenção básica (apoio matricial limitado), e a persistência de estigmas socioculturais que ainda favorecem a institucionalização.","D":"a inexistência de políticas públicas voltadas à prevenção de transtornos mentais e a exclusão total da participação de organizações não-governamentais na rede de cuidados.","E":"a predominância de abordagens biomédicas nos CAPS, que impede a inserção de terapias ocupacionais e artísticas, sem considerar a necessidade de monitoramento epidemiológico."},"answer":"C","assunto":"Reforma Psiquiátrica e Psiquiatria Social","topico":"Reforma Psiquiátrica Brasileira"},{"id":"uepa-2026-020","number":20,"area":"Psiquiatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Maria, 38 anos, residente em zona urbana periférica, tem histórico de transtorno depressivo recorrente há 10 anos. Nos últimos três meses, apresentou piora do humor, isolamento social e pensamentos de inutilidade. Ela já foi internada duas vezes em hospital psiquiátrico (2009 e 2016) por risco de suicídio. Atualmente, procura a Unidade Básica de Saúde (UBS) da sua comunidade, onde a equipe de saúde da família (enfermeiro, agente comunitário e médico de família) a recebe. Durante a consulta, o médico de família identifica risco moderado de suicídio, mas sente insegurança para iniciar farmacoterapia antidepressiva e para conduzir o plano de segurança. Ele registra o caso no prontuário eletrônico da UBS e solicita apoio matricial ao CAPS II da região. Dentro de 48 h, um psiquiatra do CAPS realiza teleconsulta, orienta a equipe quanto à escolha do antidepressivo, define critérios de monitoramento diário e indica que a enfermeira da UBS faça visitas domiciliares para aferir adesão e sinais de alerta. Além disso, o CAPS oferece treinamento presencial de 4 h para toda a equipe da UBS sobre manejo de crises suicidas. Uma semana depois, Maria inicia o tratamento na própria comunidade, com acompanhamento diário pela enfermeira, consultas mensais com o médico de família e supervisão semanal do psiquiatra do CAPS via telemedicina. Não houve necessidade de nova internação. A alternativa que sintetiza o papel do apoio matricial nesse cenário é:","options":{"A":"o apoio matricial consiste apenas em encaminhar o paciente da UBS ao CAPS para internação, deixando a equipe da atenção básica responsável apenas pelo registro administrativo do caso.","B":"através do apoio matricial, a equipe da atenção básica recebeu orientação clínica, capacitação pontual e suporte técnico contínuo do CAPS, permitindo que o tratamento fosse mantido no território, evitando nova internação.","C":"o apoio matricial implica que o CAPS assuma integralmente o cuidado de Maria, substituindo a equipe da UBS por profissionais especializados, enquanto a equipe da atenção básica passa a exercer somente funções de vigilância sanitária.","D":"a estratégia de apoio matricial limita-se à realização de um único treinamento presencial, sem necessidade de acompanhamento clínico posterior, pois a competência da equipe da UBS já seria suficiente após a capacitação.","E":"o apoio matricial tem como objetivo principal a coleta de indicadores epidemiológicos sobre depressão na comunidade, não influenciando diretamente as decisões terapêuticas individuais."},"answer":"B","assunto":"Reforma Psiquiátrica e Psiquiatria Social","topico":"Rede de Atenção Psicossocial (RAPS)"},{"id":"uepa-2026-021","number":21,"area":"Hematologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Na investigação diagnóstica de um paciente internado com anemia, em qual das seguintes situações clínicas a anemia ferropriva é a causa mais provável?","options":{"A":"mulher de 64 anos com glossite, disfagia e unhas em colher (coiloniquia).","B":"executivo de 50 anos com dispepsia crônica.","C":"mulher multípara de 39 anos com sangramento vaginal irregular e fadiga progressiva.","D":"idosa de 72 anos com palidez, parestesia e dificuldade para marcha e equilíbrio.","E":"dor no hipocôndrio esquerdo, anemia em um homem de 30 anos."},"answer":null,"assunto":"Anemias microcíticas","topico":"Anemia ferropriva","annulled":true},{"id":"uepa-2026-022","number":22,"area":"Hematologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Você está avaliando um homem de 50 anos que apresenta dor abdominal e diarreia crônica. Refere também fadiga e dispneia aos esforços nos últimos dois meses. Ao exame físico, observa-se palidez cutaneomucosa ++/4+, sem icterícia, e fígado e baço não são palpáveis. O hemograma mostra anemia microcítica e hipocrômica com plaquetose. Assinale a alternativa que apresenta a conduta mais adequada para este caso.","options":{"A":"Solicitar dosagem de ferro, ferritina, bilirrubinas e DHL, e iniciar sulfato ferroso junto às refeições.","B":"Solicitar dosagem de ácido fólico, vitamina B12, contagem de reticulócitos e prescrever sulfato ferroso endovenoso devido à diarreia, reavaliando em três meses.","C":"Iniciar imediatamente sulfato ferroso e solicitar eletroforese de hemoglobina para descartar traço talassêmico.","D":"Solicitar dosagem de ferro sérico e ferritina e iniciar investigação imediata da causa da anemia.","E":"Solicitar pesquisa de anticorpos anti-célula parietal."},"answer":"D","assunto":"Anemias microcíticas","topico":"Anemia ferropriva"},{"id":"uepa-2026-023","number":23,"area":"Hematologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Uma mulher de 22 anos apresenta sangramentos gengivais ao escovar os dentes, equimoses após pequenos traumas e menstruações prolongadas desde a adolescência. Ao exame, há petéquias e equimoses, sem hepatoesplenomegalia. O exame que avalia a hemostasia primária, cuja alteração explica o quadro clínico da paciente, é:","options":{"A":"Fibrinogênio","B":"Tempo de Protrombina (TP)","C":"Tempo de Tromboplastina parcial (TTPa)","D":"Tempo de Trombina","E":"Tempo de sangramento"},"answer":"E","assunto":"Hemostasia","topico":"Laboratório da hemostasia"},{"id":"uepa-2026-024","number":24,"area":"Cardiologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 35 anos apresenta dispneia aos esforços e queixa-se de palpitações ocasionais. Ao exame, observa-se sopro sistólico em crescendo-decrescendo no foco mitral, irradiando para borda esternal esquerda. Durante a manobra de Valsalva (fase de esforço), o sopro aumenta claramente de intensidade. Qual das valvopatias abaixo é mais compatível com esta resposta ao Valsava?","options":{"A":"Estenose aórtica.","B":"Comunicação interatrial com hiperfluxo (sopro de ejeção).","C":"Miocardiopatia Hipertrófica Obstrutiva (MHO).","D":"Insuficiência mitral.","E":"Insuficiência tricúspide."},"answer":"C","assunto":"Cardiomiopatias","topico":"Cardiomiopatia hipertrófica"},{"id":"uepa-2026-025","number":25,"area":"Endocrinologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 57 anos, com diabetes melito tipo 2 há 6 anos, hipertensão arterial bem controlada e obesidade grau I (IMC 31 kg/m²), comparece à consulta para reavaliação. Atualmente está usando metformina 850 mg 2 x dia, com boa tolerância. Nega hipoglicemias. Relata piora do controle glicêmico nos últimos 8 meses. Alimentação rica em carboidratos e vida sedentária. PA: 128/78 mmHg. História familiar: pai com IAM aos 52 anos. Exames: Hemoglobina glicada: 8,6%. Glicemia jejum: 186 mg/dL Taxa de filtração glomerular: 62 mL/min/1,73m². Microalbuminúria: 50mg/dia. Perfil lipídico: LDL 98mg/dL; HDL 41mg/dL; Triglicérides 186mg/dL. Ecocardiograma: sem alterações importantes. Paciente relata desejo de perder peso. A melhor opção terapêutica a ser acrescentada ao tratamento deste paciente, é:","options":{"A":"Sulfonilureia (como glimepirida) para maior redução da HbA1c.","B":"Inibidor de DPP-4 (como sitagliptina), pela boa tolerabilidade.","C":"Pioglicatona.","D":"Insulina basal de ação prolongada.","E":"Agonista do GLP-1 (semaglutida ou tirzepatida), visando perda de peso e proteção cardiovascular."},"answer":"E","assunto":"Diabetes ","topico":"Diabetes Mellitus tipo 2 (DM 2)"},{"id":"uepa-2026-026","number":26,"area":"Infectologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um paciente com choque séptico está em tratamento com piperacilina-tazobactam 4g/0,5g, atualmente administrada em infusão intermitente (30 min a cada 6 horas). Considerando a necessidade de otimizar a eficácia antimicrobiana, a equipe propõe a administração em infusão prolongada ou contínua. Essa estratégia tem como principal fundamento farmacodinâmico:","options":{"A":"aumentar o pico sérico (Cmax) em relação à CIM, melhorando a atividade bactericida.","B":"maximizar a fração do tempo em que a concentração plasmática do fármaco permanece acima da CIM (fT > CIM).","C":"reduzir o volume de distribuição e, com isso, melhorar a biodisponibilidade tecidual.","D":"aumentar o clearance do antibiótico, reduzindo o risco de efeitos adversos.","E":"favorecer a concentração intracelular para atuação contra patógenos intracitoplasmáticos."},"answer":"B","assunto":"Microbiologia e Antimicrobianos","topico":"Princípios da terapia antimicrobiana"},{"id":"uepa-2026-027","number":27,"area":"Infectologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 72 anos, em pós-operatório de colectomia esquerda, internado há 28 dias em UTI em ventilação mecânica. Evolui com febre, hipotensão e secreção purulenta traqueal. A cultura de aspirado traqueal colhida há 48h revelou Acinetobacter Baumannii Carbapenem-resistente, produtor de OXA-23. Ele está em uso de colistina + meropenem há 5 dias, com piora clínica e aumento da creatinina. A equipe considera o uso de antibióticos de última geração. Em relação às opções disponíveis, assinale a alternativa correta.","options":{"A":"Taniborbactam associado a cefepime tem excelente ação contra OXA-23 e deve substituir colistina.","B":"Cefiderocol pode ser considerado, pois mantém atividade contra Acinetobacter produtor de OXA-23, mesmo após falha de colistina.","C":"Taniborbactam é ativo contra todas as classes de carbapenemases, incluindo metalo-β-lactamases e oxacilinases.","D":"Cefiderocol deve ser evitado em infecções pulmonares por Acinetobacter devido a falha demonstrada em poucos estudos clínicos.","E":"A melhor abordagem é manter colistina associada a meropenem em dose estendida, pois nenhum antibiótico moderno cobre OXA-23 de forma segura."},"answer":"B","assunto":"Microbiologia e Antimicrobianos","topico":"Antibacterianos"},{"id":"uepa-2026-028","number":28,"area":"Endocrinologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Sobre o manejo farmacológico da osteoporose, analise os casos a seguir e assinale a alternativa em que há indicação correta de iniciar terapia específica para osteoporose.","options":{"A":"Mulher, 55 anos, menopausa há 3 anos, T-score de –1,0 na coluna lombar, FRAX com risco de fratura maior de 8% e de fratura de quadril de 1,5%. O médico indica ácido zoledrônico anual como estratégia preventiva precoce.","B":"Homem, 60 anos, T-score de –2,0 em colo femoral, sem fraturas prévias, porém com deficiência de vitamina D (17 ng/mL) e hiperparatireoidismo secundário. O médico inicia alendronato imediatamente na mesma consulta.","C":"Mulher, 48 anos, artrite reumatoide em uso de prednisona 10 mg/dia há 5 anos, T-score de –2,3 no fêmur e sem fraturas prévias. O médico decide apenas suplementar cálcio e vitamina D e reavaliar densitometria em 1 ano.","D":"Mulher, 72 anos, T-score de –2,4 na coluna lombar e fratura vertebral por fragilidade documentada por radiografia. A equipe inicia terapia com bisfosfonato ou anabólico, além de correção de vitamina D e cálcio.","E":"Homem, 59 anos, DMO com T-score –2,1, fratura de quadril há 3 anos e doença renal crônica em estágio 5 em hemodiálise. É iniciado alendronato semanal, pois não há contraindicação em estágio avançado de doença renal."},"answer":"D","assunto":"Metabolismo Ósseo e Mineral","topico":"Distúrbios do remodelamento ósseo"},{"id":"uepa-2026-029","number":29,"area":"Reumatologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Uma mulher de 52 anos é internada com insuficiência renal aguda rapidamente progressiva, acompanhada de artralgias, púrpura palpável em membros inferiores e fadiga intensa há duas semanas. Relata também parestesia distal, episódios de fenômeno de Raynaud no inverno e uma história de hepatite C crônica tratada irregularmente. Ao exame físico, apresenta PA 160/100 mmHg sem sinais pulmonares relevantes. Abdome sem hepatoesplenomegalia. Presença de púrpuras não trombocitopênicas nas pernas. Exames laboratoriais: creatinina: 3,1mg/dL; C4: indetectável; C3: baixo; Fatores reumatoides e FAN: negativos; Anti-dsDNA: negativo; ANCA: negativo; PCR; elevada; Anti-HCV positivo. Exame de urina: hemácias dismórficas, proteinúria 2g/24h. A biópsia renal revela: Glomerulonefrite membranoproliferativa com hipercelularidade e depósitos subendoteliais. Imunofluorescência: IgM e C3 em padrão granular, além de depósitos de C1q, formando aspecto “em mosaico” (pseudoclobetas); presença de trombos intraluminais PAS-positivos compatíveis com crioclobs. O diagnóstico mais provável, neste caso, é:","options":{"A":"Glomerulonefrite lúpica classe IV.","B":"Granulomatose com poliangiite.","C":"Granulomatose eosinofílica com poliangiite.","D":"Crioglobulinemia mista associada ao HCV.","E":"Glomerulonefrite pós-estreptocócica."},"answer":"D","assunto":"Vasculites","topico":"Vasculites de pequenos vasos"},{"id":"uepa-2026-030","number":30,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Uma mulher de 34 anos, previamente saudável, é submetida a colecistectomia videolaparoscópica sob anestesia geral com sevoflurano e succinilcolina. Cerca de 30 minutos após o término do procedimento, ainda na sala de recuperação anestésica, desenvolve taquicardia (160 bpm), hipertensão inicial seguida de hipotensão (70/40 mmHg), rigidez generalizada e temperatura central de 40,5°C. O anestesista relata aumento progressivo e inexplicado da concentração máxima de CO₂ exalada ao final da expiração e corresponde (ETCO₂) intraoperatório. A gasometria arterial e exames mostram: pH- 7.10; PaCO₂- 75mmH; PaO₂- 103mmHg; HCO₃⁻- 13mEq/L; Lactato- 8,1 mmol/L; CPK- 9.500U/L e K⁺ 7,8 mEq/L. ECG demonstra QRS largo, ondas T apiculadas e extrassístoles ventriculares. A equipe se prepara para intubação de resgate e administração de gluconato de cálcio para estabilização de membrana. A próxima conduta prioritária que realmente muda a fisiopatologia do quadro, é:","options":{"A":"Gluconato de cálcio endovenoso.","B":"Dantrolene endovenoso.","C":"Bicarbonato de sódio em bolo endovenoso.","D":"Adrenalina em infusão contínua.","E":"Dipirona em infusão contínua."},"answer":"B","assunto":"Princípios da Anestesiologia","topico":"Agentes Anestésicos","subtopico":"Agentes Inalatórios"},{"id":"uepa-2026-031","number":31,"area":"Pneumologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 58 anos, pedreiro, com exposição a tabaco por 35 maços-ano e exposição ocupacional a poeiras, relata dispneia progressiva há 2 anos e duas exacerbações nos últimos 12 meses, sendo uma com necessidade de corticoide sistêmico. Ao exame físico, apresenta tórax em barril, murmúrio vesicular globalmente diminuído e expiração prolongada. A espirometria pós-broncodilatador mostrou: VEF₁/CVF = 0,62; VEF₁ = 48% do previsto; DLCO reduzido. Na avaliação de sintomas e risco, apresenta mMRC = 3 e duas exacerbações no último ano, sendo uma grave. O paciente relata que usa LAMA isolado, mas mantém sintomas importantes. A conduta mais adequada segundo as recomendações GOLD 2024–2025, é:","options":{"A":"aumentar a dose do LAMA isolado.","B":"manter LAMA e iniciar corticoterapia inalatória isolada.","C":"iniciar associação LABA + LAMA.","D":"iniciar LABA + LAMA + ICS (“terapia tripla”).","E":"solicitar TC de alta resolução antes de alterar a terapêutica."},"answer":"D","assunto":"Doença Pulmonar Obstrutiva Crônica (DPOC)","topico":"Tratamento"},{"id":"uepa-2026-032","number":32,"area":"Nefrologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 82 anos, previamente hígido, é admitido no pronto socorro com história de diarreia profusa há 5 dias, redução da ingesta hídrica e piora progressiva do estado mental. A família nega uso de diuréticos, vômitos ou doenças prévias. Ao exame: sonolento, hipoperfundido, respiração rápida e superficial, PA 90/58 mmHg, FC 112 bpm, FR 26 irpm, pulsos finos. Exame neurológico sem sinais focais. Exames na admissão: Gasometria arterial em ar ambiente: pH = 7,21; PaCO₂ = 38mmHg; PaO₂ = 85mmHg; HCO₃⁻ = 14 mEq/L; BE = – 12; Lactato = 2,8 mmol/L; Na⁺ = 140 mEq/L; Cl⁻ = 107 mEq/L. A interpretação mais provável do distúrbio acidobásico, neste caso, é:","options":{"A":"acidose metabólica pura, com compensação respiratória adequada segundo Winter.","B":"distúrbio misto com acidose metabólica e alcalose metabólica.","C":"acidose metabólica com alcalose respiratória compensatória.","D":"distúrbio misto com acidose metabólica e alcalose respiratória.","E":"acidose metabólica com acidose respiratória associada."},"answer":"E","assunto":"Distúrbios do equilíbrio acidobásico (DHE)","topico":"Distúrbios metabólicos "},{"id":"uepa-2026-033","number":33,"area":"Reumatologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Em qual das situações clínicas abaixo o diagnóstico de Espondilite Anquilosante (EA) deve ser mais fortemente considerado?","options":{"A":"Homem de 27 anos com dor lombar baixa intermitente há 8 anos, piora ao caminhar longas distâncias e melhora em repouso; exame físico sem limitação de mobilidade.","B":"Homem de 30 anos com dor lombar insidiosa há 6 anos, rigidez matinal por > 1h, acorda à noite por dor lombar e relata melhora importante com prática regular de atividade física; refere episódios recorrentes de dor glútea alternante.","C":"Homem de 45 anos com dor lombar contínua há 4 anos, irradiando para face posterior da coxa, piora ao sentar e melhora com repouso e analgésicos simples; teste de Lasègue positivo.","D":"Homem de 34 anos com dor lombar leve e recorrente há 10 anos, agora com episódio abrupto de dor intensa e incapacidade de movimentar o hálux direito após carregar peso.","E":"Mulher de 28 anos com dor lombar leve e recorrente há 2 anos, agora com episódio abrupto de dor intensa e incapacidade de movimentar o pé direito após carregar peso."},"answer":"B","assunto":"Artropatias inflamatórias","topico":"Espondiloartrites"},{"id":"uepa-2026-034","number":34,"area":"Medicina Preventiva","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A sarcopenia e o envelhecimento muscular estão associados a alterações estruturais e funcionais das fibras musculares esqueléticas. Considerando os efeitos do envelhecimento sobre os diferentes tipos de fibras. A alternativa que descreve corretamente a mudança predominante observada na musculatura de idosos, é:","options":{"A":"aumento proporcional de fibras do tipo I (oxidativas) com redução seletiva de fibras do tipo II (rápidas).","B":"aumento predominante de fibras do tipo II, com redução da densidade de fibras tipo I.","C":"redução isolada do diâmetro das fibras do tipo I com preservação das fibras tipo II.","D":"aumento absoluto do número de fibras I e II devido à hiperplasia compensatória.","E":"conversão predominante de fibras tipo I em fibras tipo II com perda de resistência muscular."},"answer":"A","assunto":"Medicina de Família e Comunidade","topico":"Saúde do Idoso (geriatria)","subtopico":"Fisiologia do Envelhecimento"},{"id":"uepa-2026-035","number":35,"area":"Dermatologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 42 anos, previamente hígido, iniciou carbamazepina há 6 semanas para neuralgia do trigêmeo. Apresenta quadro progressivo de febre alta, mal-estar, edema facial e exantema morbiliforme difuso com áreas de descamação. Ao exame, há linfadenomegalia generalizada, icterícia leve e acometimento de mucosa oral. Não há lesões alvo típicas. O descolamento epidérmico envolve < 5% da superfície corporal. Laboratório: Eosinófilos: 2.800/mm³; Transaminases: ALT 320 U/L / AST 220 U/L; Creatinina: normal; DHL: aumentada; VHS e PCR elevados; IgE: aumentada; Sorologias virais negativas, PCR para HHV-6 positivo. Biópsia de pele: dermatite interface com infiltrado linfocitário e eosinofílico. O diagnóstico mais provável, neste caso, é:","options":{"A":"Síndrome de Stevens-Johnson associado a reação exantemática simples.","B":"NET (Necrólise Epidérmica Tóxica) precoce com envolvimento sistêmico.","C":"Síndrome DRESS induzida por carbamazepina com reativação viral.","D":"Eritema multiforme maior secundário a infecção herpética.","E":"Reação exantemática simples por hipersensibilidade tardia."},"answer":"C","assunto":"Farmacodermias","topico":"Farmacodermias graves"},{"id":"uepa-2026-036","number":36,"area":"Cardiologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 56 anos, hipertenso em uso de enalapril há 4 anos, apresenta edema súbito de lábios e glote, estridor, dificuldade respiratória e sensação de “morte iminente” minutos após ingerir camarão durante uma confraternização. Ao chegar ao pronto-socorro, encontra-se ansioso, com fala incompreensível, sialorreia, PA- 90/50mmHg, FC- 128 bpm, SatO₂ 88% em ar ambiente, sem urticária visível. Não há história prévia de alergias. O médico plantonista questiona se o quadro pode ser angioedema bradicinérgico ou anafilaxia. A conduta inicial mais apropriada, neste caso, é:","options":{"A":"administrar adrenalina IM imediatamente na face anterolateral da coxa, mesmo na ausência de urticária.","B":"iniciar adrenalina EV em infusão lenta após pré-tratamento com anti-histamínicos.","C":"administrar icatibanto ou concentrado de C1 esterase antes de considerar adrenalina.","D":"administrar apenas anti-histamínico e corticoide, pois a ausência de urticária sugere angioedema bradicinérgico.","E":"indicar intubação orotraqueal imediata antes de qualquer outra medida terapêutica."},"answer":"A","assunto":"Choque","topico":"Tratamento"},{"id":"uepa-2026-037","number":37,"area":"Cardiologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 58 anos, com IAM prévio tratado com angioplastia há 3 meses, está em uso de AAS + clopidogrel + atorvastatina. Mantém estilo de vida adequado, sem sangramentos ou efeitos adversos. Contudo, retorna ao pronto-socorro com dor torácica e nova elevação de troponina. A cineangiografia revela trombose do stent, apesar da adesão medicamentosa. Foi solicitada avaliação farmacogenômica de rotina pós-evento, revelando: CYP2C19 2 / 2 Lof (loss-of-function, metabolizador pobre); SLCO1B1 c.521CC (alto risco de miopatia com estatinas). Genótipo normal para CES1, ABCB1 e CYP3A4. A conduta mais adequada para reduzir o risco de novo evento trombótico, considerando o perfil farmacogenético, é:","options":{"A":"substituir clopidogrel por prasugrel ou ticagrelor devido à ineficácia mediada por CYP2C19.","B":"manter clopidogrel e aumentar a dose, para 150mg/fis.","C":"suspender a dupla antiagregação e introduzir anticoagulação plena com rivaroxabana.","D":"trocar atorvastatina por rosuvastatina devido ao genótipo SLCO1B1.","E":"suspender estatina e manter apenas antiagregação até completar 12 meses pós-IAM."},"answer":"A","assunto":"Aterosclerose e Doença Arterial Coronariana","topico":"Síndrome Coronariana Aguda sem Supradesnível do Segmento ST (SCASSST)"},{"id":"uepa-2026-038","number":38,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Uma mulher de 35 anos, sem comorbidades, procura aconselhamento genético após sua irmã de 38 anos receber diagnóstico de câncer de mama triplo-negativo. Sua mãe faleceu aos 44 anos por câncer de ovário seroso de alto grau. A paciente não possui filhos e ainda não realizou mamografia. O painel de NGS revelou uma variante patogênica em BRCA1. Exames físicos e laboratoriais são normais. Com base no risco genético e nas evidências disponíveis. A estratégia abaixo mais adequada neste momento, é:","options":{"A":"acompanhar anualmente apenas com mamografia a partir dos 40 anos.","B":"recomendar Ressonância Mamária com contraste anual a partir de agora e considerar salpingooforectomia redutora a partir dos 35–40 anos.","C":"iniciar quimioprevenção com tamoxifeno imediatamente, pois reduz câncer de mama associado a BRCA1.","D":"solicitar PET-CT anual como estratégia de rastreamento em portadoras de BRCA.","E":"realizar mastectomia bilateral preventiva obrigatória antes dos 35 anos, independentemente de preferência da paciente."},"answer":"B","assunto":"Mastologia","topico":"Câncer de mama","subtopico":"Prevenção"},{"id":"uepa-2026-039","number":39,"area":"Nefrologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Você está atendendo no pronto-socorro em uma manhã de segunda-feira quando é chamada para avaliar uma paciente de 51 anos com fraqueza muscular e picos hipertensivos. Relata que nos últimos dias tem sentido “tremores”, cansaço intenso e cãibras nas pernas, piorando progressivamente. Refere dificuldade para controlar a pressão arterial nas últimas semanas, mesmo utilizando corretamente losartana 100 mg/dia. Também é diabética tipo 2, em uso regular de metformina 1 g/dia. A pressão arterial na admissão era 180 × 110 mmHg. Exames colhidos na triagem: potássio: 2,5 mEq/L; sódio: 143mEq/L; HCO₃: 32mEq/L; pH arterial: 7,49; creatinina: 0,8 mg/dL. Ao explorar hábitos, menciona que há 2 meses passou a consumir diariamente 15 balas dietéticas para controlar a vontade de comer doces. Quando questionada especificamente, informa que o rótulo menciona \"extrato de alcaçuz\". Ela também tomou naproxeno 250 mg 12/12h por 3 dias devido à lombalgia, não usa diuréticos. O diagnóstico ou mecanismo mais provável para explicar o quadro da paciente, é:","options":{"A":"Hipocalemia e hipertensão secundárias ao uso recente de AINE.","B":"Hipocalemia induzida pela losartana.","C":"Hiperaldosteronismo primário.","D":"efeito adverso metabólico da anlodipina.","E":"Pseudohiperaldosteronismo por ingestão crônica de alcaçuz (glicirrizina)."},"answer":"E","assunto":"Distúrbios do potássio ","topico":"Hipocalemia"},{"id":"uepa-2026-040","number":40,"area":"Reumatologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Um homem de 58 anos, portador de diabetes mellitus tipo 2 há 18 anos, chega ao ambulatório relatando rigidez progressiva das mãos nos últimos 5 meses, dificultando abotoar camisas e manusear pequenos objetos. Refere uso irregular das medicações, HbA1c de 11% e história de neuropatia periférica sensitiva. No exame físico, ao ser solicitado que una as palmas das mãos em posição de prece, observa-se incapacidade de encostar completamente as superfícies das palmas e dos dedos, mantendo um espaço residual entre as mãos. Há pele espessada no dorso dos dedos. Reflexos presentes e sem déficit motor evidente. O diagnóstico mais provável, neste caso, é:","options":{"A":"Esclerose lateral amiotrófica.","B":"Síndrome de Dupuytren.","C":"Artropatia diabética da mão.","D":"Artrite reumatoide inicial.","E":"Neuropatia periférica diabética motora."},"answer":"C","assunto":"Doenças sistêmicas com manifestações reumatológicas","topico":"Artropatias associadas a doenças endocrinológicas"},{"id":"uepa-2026-041","number":41,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Durante atendimento a um paciente politraumatizado, foi identificado desconforto respiratório moderado, FR 30, sat O2 93% em ar ambiente. No exame físico, possuía expansão torácica assimétrica e murmúrio vesicular abolido em hemitórax esquerdo. Diante da necessidade de uma drenagem torácica, o melhor local para a inserção do dreno, é:","options":{"A":"no 2° espaço intercostal na linha hemiclavicular à esquerda.","B":"no 5° espaço intercostal na linha hemiclavicular à esquerda.","C":"no 5° espaço intercostal na linha axilar média à direita .","D":"no 5° espaço intercostal na linha axilar média à esquerda.","E":"no 3° espaço intercostal na linha axilar média à direita."},"answer":"D","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Trauma Torácico"},{"id":"uepa-2026-042","number":42,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente previamente hígido, 45 anos, comparece ao pronto socorro com queixa de dor difusa abdominal, vômitos, diarreia e mal estar iniciados há 1 dia. Durante o exame físico, percebe-se a presença de uma cicatriz abdominal devido uma cirurgia eletiva prévia de colecistectomia aberta. O nome e a localização desse tipo de incisão é:","options":{"A":"incisão de Rockey-Davis, localizada transversalmente em fossa ilíaca direita.","B":"incisão de Kocher, localizada obliquamente em região de hipocôndrio esquerdo.","C":"incisão de Mcburney, localizada obliquamente em região de fossa ilíaca direita.","D":"incisão mediana, localizada em epigástrio.","E":"incisão de Kocher, localizada obliquamente em região subcostal direita."},"answer":null,"assunto":"Vesícula e Vias Biliares","topico":"Colecistectomia","subtopico":"Colecistectomia Aberta","annulled":true},{"id":"uepa-2026-043","number":43,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A internação prolongada de pacientes graves em leitos de UTI pode aumentar o risco de lesões cutâneas relacionadas ao aumento da pressão nos tecidos de certas áreas do corpo a depender da posição do paciente. O local mais frequente para o surgimento dessas lesões, relacionando com a posição do paciente é:","options":{"A":"região sacral, quando paciente permanece mais tempo em decúbito lateral.","B":"região trocantérica, quando paciente permanece em decúbito lateral.","C":"região occipital, quando paciente se encontra em posição prona.","D":"região da face, quando paciente fica em decúbito dorsal.","E":"região do ísquio, quando paciente permanece em posição prona."},"answer":"B","assunto":"Cirurgia Plástica","topico":"Lesões Por Pressão","subtopico":"Fisiopatologia"},{"id":"uepa-2026-044","number":44,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Você atende um paciente que sofreu corte contuso em região da perna em uma barra de ferro acidentalmente. Após limpeza local, anestesia e sutura você o libera para casa com algumas orientações. Isso o faz lembrar no plantão sobre o processo de cicatrização de feridas, então discute com o outro colega plantonista sobre as etapas desse processo. Assim, é correto afirmar que:","options":{"A":"a fase proliferativa, que se inicia por volta do terceiro dia após a lesão, é caracterizada pela intensa atividade fagocitária dos macrófagos, que causam o desbridamento da ferida.","B":"a fase inflamatória é a fase inicial, dura cerca de 1 a 6 dias e é responsável pelo processo de hemostasia e quimiotaxia dos leucócitos.","C":"a fase de remodelação tem início por volta da segunda semana e apresenta intensa angiogênese e início da produção de colágeno tipo I.","D":"a fase de maturação caracteriza o final do processo da cicatrização, que pode durar cerca de um ano e é responsável pela substituição de colágeno tipo I em tipo III.","E":"na fase de proliferação, as principais células presentes na ferida são os miofibroblastos que são responsáveis pelo processo de contração da ferida."},"answer":null,"assunto":"Cicatrização de Feridas","topico":"Fases da Cicatrização ","subtopico":"Fase Inflamatória","annulled":true},{"id":"uepa-2026-045","number":45,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A artéria retal média tem origem na artéria:","options":{"A":"mesentérica superior","B":"sigmoideana","C":"sacral média","D":"mesentérica inferior","E":"ilíaca interna"},"answer":null,"assunto":"Urgências Abdominais","topico":"Abdome Agudo Vascular","subtopico":"Anatomia Vascular do Trato Gastrointestinal","annulled":true},{"id":"uepa-2026-046","number":46,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"O que define a via aérea definitiva?","options":{"A":"cateter nasal de oxigênio.","B":"ventilação com máscara laríngea.","C":"tubo posicionado na traqueia com cuff insuflado.","D":"ventilação com máscara de oxigênio em 15l.","E":"tubo posicionado na faringe com cuff insuflado."},"answer":"C","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Via Aérea Definitiva"},{"id":"uepa-2026-047","number":47,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente, FAM, 35 anos, foi levado ao HMS pela equipe do SAMU com relato de acidente de moto X carro. Após avaliação médica foi aventada a possibilidade de trauma de uretra. Sobre o trauma de uretra, assinale a alternativa correta.","options":{"A":"Em caso de trauma de uretra deve ser realizada sondagem vesical de demora por profissional experiente.","B":"A fratura de bacia é associada à lesão de uretra membranosa.","C":"A fratura de bacia está relacionada a lesão de uretra peniana.","D":"O exame ideal para diagnóstico de trauma de uretra é a cintilografia renal.","E":"O diagnóstico de trauma de uretra é feito com radiografia de pelve."},"answer":null,"assunto":"Trauma","topico":"Trauma Abdominal e Pélvico","subtopico":"Traumatismo Urológico","annulled":true},{"id":"uepa-2026-048","number":48,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente vítima de acidente de trânsito moto X carreta apresentou traumatismo craniano. Na avaliação do ATLS na escala de coma de glasgow (ECG) estava apresentando abertura ocular ao comando de voz, emitindo sons inaudiveis, localiza a dor na resposta motora e pupilas isofotorreagentes. A pontuação da ECG deste paciente é:","options":{"A":"13","B":"8","C":"7","D":"9","E":"10"},"answer":null,"assunto":"Trauma","topico":"Traumatismo Cranioencefálico","subtopico":"Classificação","annulled":true},{"id":"uepa-2026-049","number":49,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Vítima de acidente moto X moto dá entrada no hospital municipal de Santarém apresentando ao exame físico hipertimpanismo em hemitórax direito e hipotensão. A conduta a ser tomada neste caso é:","options":{"A":"intubação orotraqueal imediata.","B":"inserção de Jelco calibroso em 5º espaço intercostal ligeiramente anterior à linha axilar média do hemitórax direito e hipotensão direito.","C":"toracotomia exploradora.","D":"curativo em 3 pontos.","E":"ventilação com máscara de oxigênio em 15l."},"answer":"B","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Trauma Torácico"},{"id":"uepa-2026-050","number":50,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente vítima de ferimento por arma branca em hipocôndrio direito é submetido a laparotomia exploradora e durante a cirurgia foi identificado sangramento hepático grave. O cirurgião tomou a decisão de realizar uma manobra para bloquear o fluxo sanguíneo hepático. A manobra realizada é:","options":{"A":"Mattox","B":"Cattell","C":"C-kocher","D":"Pringle","E":"Whipple"},"answer":null,"assunto":"Trauma","topico":"Trauma Abdominal e Pélvico","subtopico":"Trauma Hepático","annulled":true},{"id":"uepa-2026-051","number":51,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação ao choque.","options":{"A":"No choque classe I há uma perda sanguínea aproximada de 20%.","B":"No choque classe II há uma perda sanguínea aproximada de 20 a 35%.","C":"No choque classe III há uma perda sanguínea aproximada de 30 a 40%.","D":"No choque classe IV há uma perda sanguínea aproximada de 35 a 45%.","E":"No choque classe V há uma perda sanguínea aproximada acima de 45%."},"answer":"C","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Choque"},{"id":"uepa-2026-052","number":52,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente vítima de explosão chega ao pronto atendimento com queimaduras de segundo grau nas porções anterior e posterior do tronco e porção anterior dos membros inferiores bilateralmente. Assinale a alternativa que contém a correta porcentagem de superfície corporal queimada segundo a regra contida no ATLS.","options":{"A":"18%","B":"27%","C":"36%","D":"45%","E":"54%"},"answer":"E","assunto":"Queimaduras e Trauma Elétrico","topico":"Atendimento Inicial às Vítimas de Queimadura","subtopico":"Manejo Hospitalar"},{"id":"uepa-2026-053","number":53,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação ao trauma abdominal.","options":{"A":"A ausência de hematúria exclui uma lesão no trato genitourinário.","B":"A contraindicação absoluta ao ultrassom FAST é a distensão abdominal devido aos gases.","C":"Uma das vantagens do lavado peritoneal é que ele pode ser repetido para comparações.","D":"A tomografia deve ser feita em pacientes com qualquer nível pressórico se há suspeita de lesão de víscera parenquimatosa.","E":"Um exame de ultrassom FAST negativo não exclui a presença de lesões viscerais."},"answer":"E","assunto":"Trauma","topico":"Trauma Abdominal e Pélvico","subtopico":"Trauma Abdominal Fechado"},{"id":"uepa-2026-054","number":54,"area":"Gastroenterologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação a composição das secreções orgânicas (em meq/L).","options":{"A":"A secreção gástrica contém mais sódio do que cloro.","B":"A secreção do intestino delgado contém mais sódio do que bicarbonato.","C":"A secreção dos cólons contém mais bicarbonato do que cloro.","D":"A secreção do pâncreas contém mais potássio do que bicarbonato.","E":"A secreção biliar contém mais potássio do que cloro."},"answer":"B","assunto":"Intestinos","topico":"Anatomia e Fisiologia do Intestino Delgado e Grosso"},{"id":"uepa-2026-055","number":55,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação à anatomia da região inguinal.","options":{"A":"O canal inguinal se estende da sínfise púbica à espinha ilíaca antero superior.","B":"O anel inguinal interno é superficial e o anel inguinal externo é profundo.","C":"O canal inguinal na mulher contém os vasos epigástricos.","D":"O cordão espermático contém, entre outras estruturas, ramos do músculo cremaster e o ramo genital do nervo genitofemoral.","E":"O cremaster é proveniente de fibras do músculo oblíquo externo."},"answer":"D","assunto":"Hérnias da Parede Abdominal","topico":"Anatomia da Parede Abdominal","subtopico":"Anatomia da Região Inguinal"},{"id":"uepa-2026-056","number":56,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação à infecção cirúrgica.","options":{"A":"Uma biópsia de mama é considerada uma cirurgia potencialmente contaminada.","B":"Toda herniorrafia com prótese é uma cirurgia potencialmente contaminada.","C":"A colecistectomia por vídeolaparoscopia é uma cirurgia limpa.","D":"A hemorroidectomia é uma cirurgia suja.","E":"O desbridamento de uma fasceíte necrotizante é considerada uma cirurgia contaminada."},"answer":null,"assunto":"Avaliação Pré-Operatória","topico":"Prevenção de Infecção da Ferida Operatória / Infecção do Sítio Cirúrgico (ISC)","subtopico":"Classificação da Cirurgia Conforme Grau de Contaminação","annulled":true},{"id":"uepa-2026-057","number":57,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Sobre os marcadores tumorais é correto afirmar que:","options":{"A":"o antígeno carcinoembrionário tem uma sensibilidade de cerca de 90% para a neoplasia de cólon.","B":"o CA 15-3 está relacionado com casos de neoplasia precoce de mama.","C":"o CA 19-9 tem alta sensibilidade e especificidade para a neoplasia de ovário.","D":"a alfafetoproteína tem uma sensibilidade de aproximadamente 98% para a neoplasia hepatocelular.","E":"o antígeno carcinoembrionário é utilizado para diagnóstico da neoplasia coloretal."},"answer":"D","assunto":"Temas Gerais em Cirurgia","topico":"Princípios da Cirurgia Oncológica"},{"id":"uepa-2026-058","number":58,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação aos sinais do exame físico abdominal e suas respectivas patologias sugeridas.","options":{"A":"Sinal de Chandelier – doença inflamatória pélvica.","B":"Sinal de Aaron – pancreatite aguda.","C":"Sinal de Danforth – apendicite aguda.","D":"Sinal de Fothergill – hemoperitônio.","E":"Sinal de ten Horn – psoíte."},"answer":"A","assunto":"Urgências Abdominais","topico":"Urgências Abdominais - Abdome Agudo","subtopico":"Avaliação da Dor Abdominal"},{"id":"uepa-2026-059","number":59,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação ao Sleeve Gástrico (SG) para tratamento cirúrgico da obesidade mórbida.","options":{"A":"O SG não preserva o piloro.","B":"No SG há aumento da síndrome de mal absorção e relação à gastroplastia em Y de Roux devido a retirada definitiva de parte do estômago.","C":"No SG há um aumento da ocorrência de hérnias internas em relação à gastroplastia em Y de Roux.","D":"No SG ocorre a redução metabólica dos níveis de grelina.","E":"O SG não permite a transformação em gastroplastia em Y de Roux caso não se tenha atingido o objetivo final."},"answer":"D","assunto":"Cirurgia Bariátrica e Metabólica","topico":"Cirurgias Restritivas","subtopico":"Gastrectomia Vertical Laparoscópica"},{"id":"uepa-2026-060","number":60,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Assinale a alternativa correta em relação à doença hemorroidária.","options":{"A":"Hemorróidas de segundo grau não são prolapsadas.","B":"A hemorroidectomia geralmente é o melhor tratamento para a doença hemorroidária a partir do terceiro grau.","C":"A técnica de Milligan-Morgan consiste em um fechamento primário da ferida pós hemorroidectomia.","D":"A melhor opção para a trombose hemorroidária é a incisão e evacuação do coágulo.","E":"As hemorróidas externas estão distais à borda anal."},"answer":"B","assunto":"Proctologia","topico":"Doenças Orificiais","subtopico":"Doença Hemorroidária"},{"id":"uepa-2026-061","number":61,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente tercigesta, sem comorbidades, com 24 semanas de gestação e histórico de realização de cerclagem uterina com 14 semanas de gestação por incompetência istmocervical, veio a consulta pré-natal em busca de orientações médicas sobre mudança de estilo de vida por desejar um melhor desfecho para a gestação atual. De acordo com recomendação do Colégio Americano de Obstetras e Ginecologistas, a melhor recomendação para o caso é:","options":{"A":"indicar a prática de atividades físicas, mas interromper caso ocorra a presença de sangramento vaginal.","B":"indicar a realização de atividades físicas em decúbito dorsal, pois levam ao aumento do débito cardíaco.","C":"contraindicar de forma absoluta a realização de atividades físicas.","D":"está indicado o treinamento de resistência muscular, para melhor adaptação do organismo às alterações posturais.","E":"há contraindicação relativa à prática de atividades físicas, logo pode-se iniciar musculação no terceiro trimestre de gestação."},"answer":"C","assunto":"Pré-natal","topico":"Assistência pré-natal","subtopico":"Avaliação do risco gestacional"},{"id":"uepa-2026-062","number":62,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente primigesta, 28 anos de idade, com 25 semanas de gestação, sem comorbidades, está em consulta de seguimento em pré-natal referindo por vezes dispnéia leve, congestão nasal e pirose. A orientação correta quanto as queixas relatadas é:","options":{"A":"explicar para a paciente que quadros de dispneia na gestação são graves, logo há necessidade de acompanhamento em pré-natal de alto risco.","B":"informar a paciente que por ação da progesterona na gestação, todo o aparelho digestivo permanece com tônus diminuído e a pirose é comum por isso.","C":"orientar a paciente que as queixas de dispneia são comuns pela hiperventilação que leva a um quadro de acidose respiratória compensada.","D":"orientar a paciente que é comum o sintoma de congestão nasal pela hipovascularização e edema da mucosa nasal na gravidez.","E":"alertar a paciente que a tríade de sintomas apresentados no momento é sinal de gravidade tanto materno quanto fetal."},"answer":"B","assunto":"Obstetrícia fisiológica","topico":"Modificações fisiológicas da gestação","subtopico":"Modificações sistêmicas"},{"id":"uepa-2026-063","number":63,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Uma paciente de 31 anos de idade, primigesta, 35 semanas de gestação, deu entrada no pronto atendimento obstétrico referindo dor abdominal súbita e intensa, com sangramento vaginal vermelho escuro e dor a palpação do útero. Ao exame físico, nota-se hipertonia uterina e taquissistolia. Pressão arterial materna de 160/110 mmHg, frequência cardíaca materna de 120 bpm e batimentos cardíacos fetais de 90 bpm. Ao exame especular há discreto sangramento vaginal e visualização de colo uterino impérvio. O registro cardiotocográfico evidencia linha de base contínua de 90 bpm, com 7 contrações uterinas fortes em 10 minutos. Com base no caso clínico, a conduta imediata para o manejo dessa paciente é:","options":{"A":"realização de cesariana imediata.","B":"indução de trabalho de parto com misoprostol.","C":"corticoterapia e cesariana em 48 horas.","D":"condução de trabalho de parto via vaginal.","E":"está indicada tocólise com nifedipino."},"answer":"A","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Sangramento segunda metade da gestação ","subtopico":"Descolamento prematuro de placenta (DPP)"},{"id":"uepa-2026-064","number":64,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Gestante G2P1, 38 semanas de gestação, comparece ao pronto atendimento obstétrico relatando perda de líquido amniótico há 1 hora. Ao exame especular, observa-se saída de líquido claro com grumos pela vagina. Ao exame físico, feto cefálico, em -2 de De Lee, colo uterino com dilatação de 2 cm, esvaecimento de 40%, consistência firme e posição centralizada, sem contrações uterinas. A paciente teve parto vaginal há 3 anos, com episiotomia mediana. Apresenta bom estado geral, sem comorbidades, sinais de infecção ou sofrimento fetal. Para o quadro apresentado, a melhor conduta é:","options":{"A":"prescrever ocitocina para condução do trabalho de parto via vaginal.","B":"indicação absoluta de cesárea, pois o índice de Bishop é desfavorável.","C":"realizar descolamento digital das membranas corioamnióticas.","D":"realização de amniotomia para coordenar as contrações.","E":"indicar maturação do colo uterino com misoprostol."},"answer":"E","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Rotura prematura de membranas ovulares (RPM)","subtopico":"Conduta na RPM"},{"id":"uepa-2026-065","number":65,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Gestante primigesta, 39 semanas de gestação, sem comorbidades, em trabalho no período expulsivo. O parto progrediu com saída da cabeça fetal, porém ocorre dificuldade na exteriorização dos ombros, com visualização de retração da cabeça fetal contra o períneo materno durante as contrações. Diante da situação exposta, a conduta correta é:","options":{"A":"realizar a hiperextensão e abdução das coxas da gestante, para auxiliar na liberação de ombro impactado.","B":"retirada do braço anterior fetal pela face anterior do tórax, na manobra de Jacquemier.","C":"tentar girar os ombros fetais do diâmetro sagital para o diâmetro oblíquo, para o desprendimento dos ombros fetais.","D":"realizar pressão mecânica no fundo uterino para desprendimento dos ombros fetais .","E":"indicar a ultimação do parto via vaginal com auxílio do fórceps Simpson-Braun."},"answer":"C","assunto":"Parto","topico":"Distocia – funcional, de objeto, de trajeto","subtopico":"De objeto"},{"id":"uepa-2026-066","number":66,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Mulher de 55 anos de idade, G2P2A0 (02 partos normais), pós menopausa há 3 anos (em uso de terapia de reposição hormonal combinada), procura atendimento ginecológico com queixa de perda urinária há 12 meses, que vem interferindo nas suas atividades diárias. Após medidas conservadoras, incluindo orientações comportamentais, nutricionais e exercícios de fortalecimento do assoalho pélvico, sem melhora significativa. O exame físico evidencia hipermobilidade uretral (sem prolapso de parede vaginal anterior e posterior), e o estudo urodinâmico mostra perda urinária associada ao aumento da pressão abdominal, sem contrações involuntárias do detrusor. Para o caso descrito, a melhor conduta é:","options":{"A":"Colporrafia anterior e posterior.","B":"Histerectomia total via vaginal.","C":"Iniciar anticolinérgico oral.","D":"Prescrever beta-3 agonista.","E":"Indicar tratamento cirúrgico com sling suburetral."},"answer":"E","assunto":"Uroginecologia","topico":"Incontinência urinária","subtopico":"Incontinência urinária aos esforços"},{"id":"uepa-2026-067","number":67,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Uma mulher de 18 anos de idade procura o pronto atendimento ginecológico com queixa de ardor ao urinar. Ao exame ginecológico, observa-se uma úlcera genital dolorosa em introito vaginal, de bordas irregulares e fundo purulento, associada a linfonodomegalia inguinal acompanhada de dor. De acordo com o caso descrito, o melhor tratamento para a paciente é:","options":{"A":"aciclovir 400 mg via oral a cada 8 horas, por 5 dias.","B":"Butoconazol em uso tópico, dose única.","C":"A penicilina G benzatina em dose única de 2,4 milhões de unidades IM.","D":"ceftriaxona 250 mg IM, em dose única.","E":"Doxiciclina 100 mg a cada 12 horas, por 21 dias."},"answer":"D","assunto":"Infecções em ginecologia","topico":"Úlceras genitais","subtopico":"Úlceras infecciosas de causa sexualmente transmissível"},{"id":"uepa-2026-068","number":68,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente de 49 anos, G2P2, com história de dois partos normais e sem cirurgias prévias, procura atendimento ginecológico com queixa de calores intensos, sudorese noturna e dificuldade para dormir, sintomas que se iniciaram após a menopausa, ocorrida há 2 anos. É hipertensa controlada em uso de losartana e nega tabagismo. Considerando o quadro clínico apresentado, a conduta terapêutica mais eficaz para o alívio dos sintomas vasomotores relatados é:","options":{"A":"terapia de reposição hormonal com estrogênio isolado.","B":"inibidores seletivos da recaptação de serotonina.","C":"terapia de reposição hormonal com estrogênio e progesterona.","D":"Estriol via vaginal.","E":"inibidores da recaptação de serotonina e norepinefrina."},"answer":"C","assunto":"Ginecologia endócrina","topico":"Climatério","subtopico":"Terapia hormonal"},{"id":"uepa-2026-069","number":69,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Paciente de 27 anos, nuligesta, usuária de DIU de cobre 380-A, inserido há 2 anos, procura atendimento ginecológico com queixa de corrimento vaginal com odor desagradável, principalmente após a relação sexual. Nega dor pélvica ou febre. Ao exame ginecológico, observa-se corrimento acinzentado, fino e homogêneo, sem sinais inflamatórios. O teste das aminas é positivo e o pH vaginal está aumentado (> 4,5). Considerando o quadro clínico descrito, a melhor conduta é:","options":{"A":"Remover o DIU de cobre e iniciar fluconazol oral.","B":"Metronidazol, mantendo o DIU de cobre.","C":"Apenas prescrever fluconazol em dose única.","D":"Clindamicina creme vaginal 2% e retirar o DIU de cobre.","E":"Ceftriaxona intramuscular e doxiciclina oral."},"answer":"B","assunto":"Infecções em ginecologia","topico":"Vulvovaginites","subtopico":"Vaginose bacteriana"},{"id":"uepa-2026-070","number":70,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Mulher de 21 anos de idade procura atendimento de urgência ginecológica relatando ter sido vítima de violência sexual com conjunção carnal há poucas horas. Refere dor intensa em região genital e sangramento discreto. Ao exame físico, observam-se lesões traumáticas em vulva e vagina, sem sinais de instabilidade hemodinâmica. Diante deste caso, a conduta adequada é:","options":{"A":"tratar lesões do canal vaginal, fazer profilaxia para Infecções Sexualmente Transmissíveis, contracepção de emergência e encaminhar para o seguimento com equipe multiprofissional.","B":"realizar sutura das lesões, prover contracepção de emergência e encaminhar a paciente para o médico legista.","C":"encaminhar a paciente diretamente para o Instituto Médico Legal (IML).","D":"encaminhar a paciente para realização de Boletim de Ocorrência (BO) e então fazer tratamento de lesões, contracepção de emergência e profilaxia para Infecções Sexualmente Transmissíveis.","E":"solicitar a presença de um familiar para acompanhar a paciente para o instituto médico legal, onde será feita contracepção de emergência e boletim de ocorrência."},"answer":"A","assunto":"Ginecologia geral","topico":"Atendimento à vítima de violência sexual","subtopico":"Atendimento"},{"id":"uepa-2026-071","number":71,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"O sistema STRAW (Stages of Reproductive Aging Workshop) caracteriza os diferentes estágios do envelhecimento do sistema reprodutivo com base em características clínicas e laboratoriais. Segundo esse sistema, uma mulher com amenorréia há 90 dias, baixa contagem de folículos ovariano, alto nível de hormônio folículo estimulante, baixo nível de hormônio antimülleriano, baixo nível de Inibina B encontra-se na seguinte fase da vida reprodutiva:","options":{"A":"Pós menopausa Tardia","B":"Pós menopausa Precoce","C":"Transição menopausal","D":"Período reprodutivo precoce","E":"Pico do período reprodutivo"},"answer":"C","assunto":"Ginecologia endócrina","topico":"Climatério","subtopico":"Definições"},{"id":"uepa-2026-072","number":72,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Mulher com 24 anos de idade referindo dor pélvica aguda de forte intensidade há 2 dias. Nega: atraso menstrual. Ao exame físico: Febre (temperatura axilar=38,10C), sinal de Giordano negativo, normocorada, pressão arterial= 110/70 mmHg, eupneica. Especular vaginal: muco cervical purulento, conteúdo vaginal amarelado com odor discreto, colo e vagina sem lesões. Toque vaginal: colo, útero e anexos dolorosos a mobilização. Abdome: normotenso, doloroso a palpação profunda em hipogástrio, descompressão brusca indolor. Considerando o quadro clínico, a principal hipótese diagnóstica dentre as opções abaixo é:","options":{"A":"Prenhez ectópica íntegra.","B":"Prenhez ectópica rota.","C":"Pielonefrite.","D":"Mioma parido.","E":"Doença inflamatória pélvica."},"answer":"E","assunto":"Infecções em ginecologia","topico":"Doença Inflamatória Pélvica","subtopico":"Diagnóstico"},{"id":"uepa-2026-073","number":73,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Mulher, 25 anos de idade, sexualmente ativa, queixando-se de pequenas vesículas agrupadas em região genital, que romperam formando úlceras dolorosas há cerca de 2 dias. Exame físico: úlceras agrupadas com fundo contendo conteúdo hialino em região genital e perianal; linfonodos inguinais não palpáveis. Especular vaginal: muco cervical cristalino, conteúdo vaginal fisiológico, colo e vagina sem lesões. Considerando o quadro acima, o agente etiológico das lesões com maior probabilidade dentre as opções abaixo é:","options":{"A":"Haemophilus ducreyi.","B":"Cândida Albicans.","C":"Trichomonas vaginalis.","D":"Herpes simplex.","E":"Klebisiella granulomats."},"answer":"D","assunto":"Infecções em ginecologia","topico":"Úlceras genitais","subtopico":"Úlceras infecciosas de causa sexualmente transmissível"},{"id":"uepa-2026-074","number":74,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A Síndrome dos Ovários Policísticos (SOP) tem ampla gama de sinais e sintomas, devendo o tratamento ser individualizado. Neste contexto, dentre as opções abaixo, a melhor opção terapêutica para uma paciente com SOP, índice de massa corpórea normal, sem sinais de hiperandrogenismo clínico, sem alterações em couro cabeludo e com desejo de engravidar é:","options":{"A":"Finasterida","B":"Espironolactona","C":"Liraglutida","D":"Drosperinona com etinilestradiol","E":"Citrato de clomifeno"},"answer":"E","assunto":"Ginecologia endócrina","topico":"Síndrome dos ovários policísticos","subtopico":"Tratamento"},{"id":"uepa-2026-075","number":75,"area":"Ginecologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Mulher, 34 anos de idade, relatando que há cerca de 1 ano apresenta ciclos menstruais longos, que variam de 60 a 90 dias. Nega outros sintomas e não apresenta sinais clínicos de hiperandrogenismo. Método contraceptivo: laqueadura tubária há 5 anos. As dosagens hormonais apresentam-se com: Folículo estimulante acima do normal, Prolactina normal e Tireoestimulante normal. Neste contexto a principal hipótese diagnóstica é:","options":{"A":"Hiperandrogenismo.","B":"Hiperprolactinemia.","C":"Hipotireoidismo.","D":"Hipertireoidismo.","E":"Falência ovariana precoce."},"answer":"E","assunto":"Ginecologia endócrina","topico":"Amenorreias","subtopico":"Amenorreia secundária"},{"id":"uepa-2026-076","number":76,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Primigesta, com 24 semanas de idade gestacional, assintomática, comparece a consulta com os seguintes exames: 1- cultura de urina mostrando duas amostras consecutivas com isolamento Escherichia coli com 100.000 unidades formadoras de colônias (UFCs) por ml de urina; 2- Tipagem sanguínea AB Rh-negativa; 3- Coombs indireto negativo. O adequado cuidado pré-natal diante destes exames deve conter:","options":{"A":"Antibioticoterapia por 7 dias e Imunoglobulina anti-D entre 28 e 34 semanas de gestação.","B":"Repetir urocultura para decidir sobre antibioticoterapia e a Imunoglobulina anti-D deverá ser realizada somente após o parto.","C":"Repetir urocultura para decidir sobre antibioticoterapia e administrar Imunoglobulina anti-D entre 28 e 34 semanas de gestação.","D":"Antibioticoterapia por 7 dias e solicitação de coombs direto materno para decidir sobre Imunoglobulina anti-D.","E":"Somente Antibioticoterapia por 14 dias."},"answer":"A","assunto":"Doenças associadas à gestação","topico":"Infecção Urinária e Bacteriúria Assintomática na gestação (ITU) "},{"id":"uepa-2026-077","number":77,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Tercigesta, 32 anos de idade, 2 filhos vivos, com gestação planejada e 10 semanas de amenorréia. Relata dor leve tipo cólica em hipogástrio e 1 episódio de pequeno sangramento vaginal há cerca de 12 horas. Exame físico: febril, eupineica, acianótica; ausência de sangramento vaginal no momento da consulta; colo uterino impérvio. Ultrassonografia transvaginal evidencia saco gestacional regular e batimentos cardíacos fetais presentes. Diante deste quadro a melhor conduta dentre as opções abaixo é:","options":{"A":"antibioticoterapia e histerectomia.","B":"antibioticoterapia seguida de aspiração manual intra-uterina.","C":"curetagem uterina com alta após 24 horas.","D":"acolhimento suporte emocional e acompanhamento com controle ultrassonográfico.","E":"iniciar misoprostol."},"answer":"D","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Sangramento primeira metade ","subtopico":"Abortamento"},{"id":"uepa-2026-078","number":78,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Gestante com 08 semanas de idade gestacional, comparece à consulta com os seguintes resultados de exame: 1- Sorologia para toxoplasmose IgM positiva e IgG positiva; 2- Teste de avidez para toxoplasmose com alta avidez. Diante destes exames a conduta inicial adequada é:","options":{"A":"tratar com espiramicina até o fim da gestação.","B":"tratar com sulfadiazina, pirimetamina, sulfadiazina e ácido folínico até o fim da gestação.","C":"iniciar sulfadiazina, pirimetamina, sulfadiazina e ácido folínico e solicitar amniocentese para pesquisa de toxoplasma no líquido amniótico.","D":"realizar amniocentese para pesquisa de toxoplasma no líquido amniótico e decidir sobre tratamento após resultado de exame.","E":"explicar para a paciente que não há necessidade de tratamento pois a infecção é antiga e a paciente é imune."},"answer":"E","assunto":"Medicina fetal","topico":"Infecções congênitas ","subtopico":"Toxoplasmose na gestação"},{"id":"uepa-2026-079","number":79,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Gestante, com 25 semanas de idade gestacional, queixando-se de dor suprapúbica, disúria, polaciúria e urgência miccional. Exame físico: colo e vagina sem lesões, muco cervical cristalino, conteúdo vaginal fisiológico; Giordano negativo bilateralmente. Paciente nega episódios anteriores deste mesmo quadro clínico. Neste contexto, logo após coletar urocultura, a conduta mais adequada dentre as opções abaixo é:","options":{"A":"tratar após resultado de urocultura, conforme sensibilidade aos antibióticos testados.","B":"antibioticoterapia oral ambulatorial sem necessidade de profilaxia com antibiótico após tratamento.","C":"antibioticoterapia intravenosa em ambiente hospitalar sem necessidade de profilaxia com antibiótico após tratamento.","D":"antibioticoterapia oral ambulatorial, iniciando profilaxia com antibiótico após tratamento.","E":"antibioticoterapia intravenosa em ambiente hospitalar, iniciando profilaxia com antibiótico após tratamento."},"answer":"B","assunto":"Doenças associadas à gestação","topico":"Infecção Urinária e Bacteriúria Assintomática na gestação (ITU) "},{"id":"uepa-2026-080","number":80,"area":"Obstetrícia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Puérpera, com 6 dias após parto normal, queixando-se de febre, dor suprapúbica e sangramento vaginal com odor fétido. Nega outras queixas. Exame físico: loquiação purulenta com odor fétido; colo uterino pérvio para 1 cm, útero amolecido; mamas túrgidas, sem flogose e indolores; Giordano negativo bilateralmente, frequência cardíaca= 107 bpm; temperatura axilar= 38,5°C. Com base nos sinais e sintomas descritos a principal hipótese diagnóstica é:","options":{"A":"Mastite puerperal.","B":"Puerpério fisiológico.","C":"Endometrite puerperal.","D":"Cistite no puerpério.","E":"Pielonefrite no puerpério."},"answer":"C","assunto":"Puerpério","topico":"Infecção puerperal / endometrite puerperal","subtopico":"Diagnóstico"},{"id":"uepa-2026-081","number":81,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Dona Rosa leva seu primogênito de 8 meses de idade, hígido, para consulta de rotina com o pediatra. Ao checar a caderneta da criança, o médico constata que o bebê não recebeu nenhuma dose da vacina contra o vírus SARS-CoV-2. Nesse contexto é correto afirmar que:","options":{"A":"a criança perdeu a oportunidade da imunização contra formas graves da COVID-19, não sendo possível iniciar o esquema vacinal na idade atual.","B":"nesta idade o bebê já deveria ter recebido uma dose da vacina contra a COVID-19, devendo iniciar o mais breve possível.","C":"o bebê deve iniciar o esquema com a vacina contra a COVD-19 na idade atual, até completar as 4 doses previstas.","D":"nesta idade o bebê já deveria ter recebido duas doses da vacina contra a COVID-19, devendo iniciar o mais breve possível.","E":"caso o bebê não tenha contraindicação, deve iniciar o esquema vacinal com doses anuais."},"answer":"D","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","subtopico":"Calendários vacinais"},{"id":"uepa-2026-082","number":82,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Você atende um lactente de 2 meses de idade na UPA, com história de febre iniciada há 24 horas. Segundo a mãe, apresentou temperatura axilar de 38oC, sendo medicado com dipirona gotas (1 gota por Kg de peso). Lactente ativo, reativo ao manuseio, sem alterações no exame físico completo. Assinale abaixo a alternativa que contém a conduta correta neste caso.","options":{"A":"Liberar para casa, orientando sinais de alerta de piora, com prescrição de paracetamol gotas (1 gota por Kg) e retorno em 24 horas.","B":"Internar, coletar exames laboratoriais incluindo coleta de líquor, Rx de tórax e iniciar antibiótico empírico.","C":"Coletar pesquisa de vírus respiratório, hemograma e sedimento urinário, aguardando resultado ainda na unidade, e orientar a mãe sobre o uso correto de antitérmico.","D":"Liberar para casa, manter o antitérmico utilizado e orientar sobre sinais de alerta de piora.","E":"Acalmar a mãe sobre o quadro, pois trata-se de infecção benigna com exame físico normal, devendo esta retornar em 48 horas para reavaliação."},"answer":"C","assunto":"Infectologia Pediátrica","topico":"Febre sem sinais localizatórios (FSSL)","subtopico":"Abordagem Diagnóstica"},{"id":"uepa-2026-083","number":83,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Criança de 5 anos de idade, é levada a emergência devido quadro de dor difusa em face anterior da tíbia e fossa poplítea de membro inferior direito, de forte intensidade, há 30 minutos. Mãe relata episódios semelhantes nos últimos 6 meses, sempre no final da tarde ou a noite, as vezes acometendo membro inferior esquerdo e membros superiores, sem outras queixas. Administra paracetamol, com melhora completa do quadro. Ao exame físico, criança ativa com fascies de dor, sem alteração na inspeção, palpação e movimentação de membros e exame físico geral sem alterações. Nesse contexto é correto afirmar que:","options":{"A":"deve ser prescrito dexametasona, pois trata-se de dor de caráter inflamatório e de forte intensidade.","B":"deve ser pensado em Munchalsen por procuração, visto que não há alterações que justifiquem a queixa.","C":"o mielograma é exame complementar essencial para a investigação diagnóstica deste paciente.","D":"a criança deve ser medicada com analgésicos e realizar exames, dentre eles o FAN, ASLO e Fator Reumatóide para afastar doenças reumatológicas.","E":"a principal hipótese diagnóstica é dor recorrente benigna em membros, a qual melhora com massagem e aquecimento do membro."},"answer":"E","assunto":"Reumatologia Pediátrica","topico":"AIJ - Artrite Idiopática Juvenil","subtopico":"Diagnóstico Diferencial"},{"id":"uepa-2026-084","number":84,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"RN do sexo masculino, nascido a termo, com peso adequado para a idade gestacional, de parto vaginal, sem intercorrências. Apresentou icterícia no segundo dia de vida, iniciando em face e progredindo para tronco no mesmo dia. Mãe primigesta, 25 anos de idade, pré-natal completo, tipagem sanguínea (TS) O positivo. Solicitados exames para o bebê: TS A positivo, Bilirrubina total 13 mg/dL, com predomínio de fração indireta, Coombs direto positivo. O diagnóstico mais provável para o caso descrito, é:","options":{"A":"Icterícia fisiológica do RN","B":"Incompatibilidade Rh","C":"Incompatibilidade ABO","D":"Icterícia do aleitamento materno","E":"Atresia de vias biliares"},"answer":"C","assunto":"Neonatologia","topico":"Icterícia nenonatal e distúrbios hematológicos no RN","subtopico":"Icterícia neonatal"},{"id":"uepa-2026-085","number":85,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Mulher de 30 anos de idade, gestante com 35 semanas de idade gestacional, dá entrada na urgência da maternidade em franco trabalho de parto. O recém nascido não chorou ao nascer, apresentando movimentos respiratórios irregulares e frequência cardíaca de 90 bpm. Foi colocado em fonte de calor radiante, cabeça posicionada em leve extensão e realizada secagem vigorosa. Após 30 segundos a FC permanecia de 90 bpm e respiração irregular. A próxima conduta imediata para este caso, é:","options":{"A":"administrar oxigênio inalatório a 100% via cânula nasal.","B":"iniciar ventilação com pressão positiva com ar ambiente (21%).","C":"iniciar massagem cardíaca com relação 3 compressões para 1 ventilação.","D":"administrar adrenalina via cateter umbilical.","E":"fazer novo estímulo tátil e aguardar resposta."},"answer":"B","assunto":"Neonatologia","topico":"Reanimação neonatal","subtopico":"Reanimação neonatal em maiores de 34 semanas"},{"id":"uepa-2026-086","number":86,"area":"Psiquiatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Durante uma consulta de rotina, a mãe de uma criança de 2 anos de idade relata que ela ainda não fala, evita contato visual e não atende quando chamada pelo nome. Ao brincar, o filho não socializa e organiza os brinquedos de forma repetitiva. A mãe trabalha em período integral e a criança fica com a babá durante o dia. Nesse contexto, a conduta mais adequada, é:","options":{"A":"aguardar até os 3 anos de idade, pois para a idade atual não há sinais de alerta.","B":"solicitar ressonância nuclear magnética de crânio.","C":"encaminhar para avaliação multidisciplinar e intervenção precoce.","D":"iniciar medicação para reduzir comportamentos repetitivos.","E":"orientar sobre estimulação domiciliar e reavaliar após 6 meses."},"answer":"C","assunto":"Psiquiatria Infantil","topico":"Transtorno do Espectro Autista (TEA)"},{"id":"uepa-2026-087","number":87,"area":"Infectologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"João, 6 anos de idade, foi a sua primeira consulta com o novo pediatra. Na anamnese, tinha como queixa principal prurido nasal com espirros principalmente pela manhã. Em seus antecedentes, cerca de 3-4 resfriados por ano, uma internação anterior devida diarreia aguda controlada 72 horas após a admissão, uma internação para tratar pneumonia bacteriana aos 4 anos (tratou em enfermaria, sem intercorrências, recebendo alta em 7 dias). Durante o exame físico, o pediatra observa diversas cicatrizes em região glútea e em coxas, as quais a mãe diz serem resultado de abscessos de repetição. Dentre os dados coletados nesta consulta, o que justifica uma investigação para erros inatos da imunidade, é:","options":{"A":"Rinite alérgica.","B":"Resfriados de repetição.","C":"Diarreia aguda.","D":"Pneumonia bacteriana.","E":"Abscessos de repetição."},"answer":"E","assunto":"Imunossuprimidos não-HIV","topico":"Imunodeficiências primárias"},{"id":"uepa-2026-088","number":88,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Menina de 7 anos de idade é levada em consulta por apresentar broto mamário e odor axilar há 6 meses. Ao exame físico, observa-se Tanner M2P1, sem outros achados. Comparando a estatura da última consulta, há 6 meses, você observa crescimento de 6 cm. Assinale a alternativa que contém a conduta mais adequada.","options":{"A":"Observar e reavaliar em 3 meses, pois pode tratar-se de telarca precoce isolada.","B":"Solicitar Rx para avaliar idade óssea, dosagem de LH, FSH e estradiol.","C":"Solicitar USG pélvica para avaliação inicial.","D":"Iniciar tratamento com análogo de GnRH.","E":"Solicitar TSH e T4 livre para investigação inicial."},"answer":"B","assunto":"Puericultura ","topico":"Puberdade","subtopico":"Distúrbios Puberais"},{"id":"uepa-2026-089","number":89,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Recém nascido do sexo masculino, nascido a termo, apresenta irritabilidade, distensão abdominal e jato urinário fraco nas primeiras horas de vida. A ultrassonografia fetal havia identificado hidronefrose bilateral do feto e oligoâmnio. Ao exame, abdômen tenso e abaulamento em hipogástrio. Com base nesses achados, o diagnóstico mais provável e exame de escolha para confirmação, são:","options":{"A":"refluxo vesicoureteral- urografia excretora.","B":"estenose de meato uretral- uretrocistoscopia.","C":"válvula de uretra posterior- uretrocistografia miccional.","D":"hidronefrose obstrutiva bilateral- ultrassonografia de rins e vias urinárias.","E":"bexiga neurogênica- cistometria."},"answer":"C","assunto":"Cirurgia Infantil","topico":"Afecções do Trato Geniturinário","subtopico":"Hidronefrose Antenatal"},{"id":"uepa-2026-090","number":90,"area":"Hematologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Joana leva seu filho Miguel, de 4 anos de idade, ao pronto atendimento devido quadro de dor em mão direita, associado a febre moderada há 48 horas. Ao exame, criança pálida (3/4+), regular estado geral, febril, com baço palpável a 4 cm do rebordo costal esquerdo, presença de dactilite em dedos de mão direita. Antecedentes pessoais: em uso de sulfato ferroso há 4 meses prescrito pelo médico do posto de saúde devido anemia. Vacinas atualizadas, teste do pezinho realizado porém sem resultado na caderneta da criança. Neste caso, o exame que deve ser solicitado para investigar a principal hipótese diagnóstica é:","options":{"A":"Eletroforese de hemoglobina.","B":"Hemocultura.","C":"Rx de mão direita.","D":"Fator reumatoide.","E":"ASLO."},"answer":"A","assunto":"Hemoglobinopatias","topico":"Anemia falciforme"},{"id":"uepa-2026-091","number":91,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Quanto ao uso de probióticos na população pediátrica, assinale a alternativa INCORRETA.","options":{"A":"A colonização inicial da microbiota intestinal é fortemente influenciada pelo tipo de parto, pela alimentação (aleitamento materno versus fórmulas), pelo uso de antibióticos e pelo ambiente.","B":"O eixo intestino-pele é responsável pelo desenvolvimento da dermatite atópica.","C":"Imaturidade imunológica, escolarização precoce e o número de irmãos favorecem o incremento na incidência de infecções de repetição.","D":"Os efeitos clínicos dos probióticos independem da cepa utilizada.","E":"Os probióticos são geralmente seguros, mas eventos adversos como distensão abdominal ou flatulência leve podem ocorrer. Entretanto, em teoria, são contraindicados em pacientes imunocomprometidos graves ou com cateter venoso central, devido ao risco, ainda que raro, de fungemia ou bacteremia."},"answer":"D","assunto":"Gastrologia Pediátrica","topico":"Diarreia Aguda ","subtopico":"Conduta medicamentosa"},{"id":"uepa-2026-092","number":92,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Quanto ao uso de corticoides sistêmicos na pediatria, é correto afirmar que:","options":{"A":"apesar da utilização de anticorpos monoclonais para tratamento de pacientes com dermatite atópica, os corticoides sistêmicos ainda são tratamento de primeira escolha em pediatria.","B":"o uso prolongado de CS em crianças com asma é contraindicado devido aos seus efeitos adversos, sendo recomendado apenas para exacerbações graves ou casos refratários.","C":"o V Consenso Brasileiro sobre Rinites (2024) recomenda o uso de corticoide sistêmico de deposito em rinite alérgica, preferencialmente por via parenteral, para rápido alivio dos sintomas e melhora de padrão respiratório.","D":"na síndrome DRESS o corticoide sistêmico está relacionado a síndrome de reconstituição imune inflamatória, sendo portanto, contra indicado o seu uso.","E":"no tratamento da anafilaxia, o corticoide é a primeira escolha medicamentosa a fazer, uma vez que evita as reações bifásicas, que são recidivas tardias que podem ocorrer entre 8 e 72 horas após o episódio inicial em até 20% dos casos."},"answer":"B","assunto":"Pneumologia Pediátrica","topico":"Asma ","subtopico":"Tratamento de Manutenção"},{"id":"uepa-2026-093","number":93,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"São características das crianças com condições crônicas complexas, EXCETO:","options":{"A":"duração mínima de 6 meses (exceto se a morte for o desfecho anterior).","B":"acometimento com disfunção de um órgão ou sistema, ou de apenas um órgão de forma grave.","C":"necessitam de acompanhamento especializado e provavelmente um período de internação em hospital terciário, com necessidades intensivas dos serviços de saúde.","D":"limitação funcional significativa, muitas vezes dependente de traqueostomia e gastrostomia.","E":"transporte de pacientes com CCC, que muitas vezes estão acamados e cujos familiares não têm condições de levá-los sozinhos aos serviços de referência é um dos obstáculos enfrentados pelos cuidadores de crianças com condições crônicas complexas."},"answer":"A","assunto":"Puericultura ","topico":"Puericultura Geral","subtopico":"Consultas em Pediatria"},{"id":"uepa-2026-094","number":94,"area":"Cirurgia Geral","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Sobre o adequado manejo da dor em pediatria, é correto afirmar que: I. O uso de escalas analgésicas de acordo com a faixa etária devem ser utilizadas para o adequado manejo da dor. II. O uso de codeína é uma recomendação forte para o manejo de dor de crianças em qualquer faixa etária. III. Deve-se preferir o uso de analgésicos via oral, sempre que possível. IV. O adequado manejo da dor pediátrica deve ser feito de horário, exceto quando se utilizar uma medicação que tenha efeito analgésico e antitérmico, devendo-se a dose ser omitida em caso de ausência de febre. V. A morfina em pediatria está associada a delirium e constipação intestinal severa, sendo contraindicada na população pediátrica. A alternativa que contém todas as afirmativas corretas é:","options":{"A":"I e III","B":"II e IV","C":"I, III e V","D":"II , III e IV","E":"I, II e III"},"answer":"A","assunto":"Princípios da Anestesiologia","topico":"Cuidados Pós-anestésicos","subtopico":"Dor e Analgesia"},{"id":"uepa-2026-095","number":95,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Quanto a imunização com BCG, é correto afirmar que: I. Deve ser aplicada em dose única o mais precocemente possível, ainda na maternidade ou na primeira visita à Unidade de Saúde. II. Não se recomenda mais a revacinação de crianças que não apresentem cicatriz no local da aplicação após 6 meses. III. Comunicantes domiciliares de hanseníase, independente da forma clínica, podem receber uma segunda dose da vacina BCG. IV. Em recém-nascidos filhos de mães que utilizaram imunossupressores na gestação, ou com história familiar de imunossupressão, a vacinação deverá ser adiada, pelo menos até os 6 meses de idade, ou contraindicada, dependendo da situação. V. Pode ser aplicada em bebês a partir de 1500 g. A alternativa que contém todas as afirmativas corretas é:","options":{"A":"I e III","B":"II e IV","C":"I, III e V","D":"I, II , III e IV","E":"II, III, IV e V"},"answer":"D","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","subtopico":"Vacina BCG"},{"id":"uepa-2026-096","number":96,"area":"Psiquiatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Adolescente de 15 anos chega ao pronto socorro com relato de Náuseas e vômitos + Dor abdominal difusa+ Cefaleia + Tontura e Fraqueza. Relata que há 4 horas ingeriu bebida alcoólica e percebe piora progressiva do quadro. Após 12 h da admissão, relata visão turva, seguida de crise convulsiva. Exames de laboratório evidenciam acidose metabólica com GAP aniônico elevado, aumento de escorias nitrogenadas e discreta elevação de transaminases. Ante o exposto, assinale a hipótese diagnóstica e tratamento adequado.","options":{"A":"insuficiência renal => correção de acidose","B":"intoxicação por metanol => etanol + hemodiálise","C":"Pancreatite => jejum e medidas de suporte","D":"arritmias => cardioversao elétrica","E":"sepse => antibioticoterapia"},"answer":"B","assunto":"Intoxicações Exógenas","topico":"Intoxicação por Metanol"},{"id":"uepa-2026-097","number":97,"area":"Neurologia","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Sobre a melatonina analise as afirmativas abaixo e assinale a correta. I. A melatonina é transferida para o recém- -nascido através do leite materno até a 12ª e 20ª semanas de vida, seguindo o ritmo circadiano. II. A partir dos três meses de idade, os lactentes começam a produzir melatonina, sendo o leite materno importante para consolidar o ritmo sono-vigília dos bebês até que seu próprio sistema circadiano amadureça. III. A exposição prolongada à luz azul emitida pelos dispositivos eletrônicos, pode prejudicar a produção da melatonina, levando a distúrbios do ritmo circadiano e alterando não apenas o sono, mas também outros processos fisiológicos como puberdade, ganho de peso, desenvolvimento da linguagem e da comunicação. IV. Apenas cinco minutos de exposição à luz azul durante à noite são capazes de bloquear a produção de melatonina, enquanto a recuperação de sua produção pode demandar horas. V. Os sintomas mais comuns da hipermelatoninemia são: sonolência diurna, tontura, hipotonia, alteração do nível de consciência e crises de síncope com sudorese e hipotermia (temperatura entre 33 e 34°C). A alternativa que contém todas as afirmativas corretas, é:","options":{"A":"I e III","B":"II e IV","C":"I, III e V","D":"I, II , III e IV","E":"I, II, III, IV e V"},"answer":"E","assunto":"Distúrbios do Sono","topico":"Fisiologia do Sono Normal"},{"id":"uepa-2026-098","number":98,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"A pneumonia necrosante, descrita em crianças desde 1994, é uma forma grave de pneumonia adquirida na comunidade, presente em até 7% dos casos pediátricos. Seu aumento não é completamente explicado pelos avanços diagnósticos, e sua fisiopatologia ainda é pouco compreendida, havendo suspeita de influência genética. Com base nesse contexto, assinale a alternativa correta.","options":{"A":"A consolidação com necrose caracteriza o estágio final da pneumonia necrosante.","B":"A necrose evolui rapidamente para cavitação (pneumatocele), geralmente periférica e multilobar. As cavidades podem coalescer, formando lesões maiores, fístulas broncopleurais e pneumotórax.","C":"Os principais agentes etiológicos são Streptococcus pneumoniae, Staphylococcus aureus e o vírus sincicial respiratório.","D":"A pneumonia necrosante localiza-se em um espectro clínico entre o abscesso pulmonar e a gangrena pulmonar.","E":"Estudos recentes não identificaram cepas de Staphylococcus aureus produtoras de leucocidina de Panton-Valentine (PVL), toxina associada a formas graves de pneumonia necrosante em crianças e adultos previamente saudáveis."},"answer":"B","assunto":"Pneumologia Pediátrica","topico":"Pneumonias/Broncopneumonias (BCP) na Infância","subtopico":"Complicações"},{"id":"uepa-2026-099","number":99,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"Lactente do sexo feminino, 8 meses de idade, foi levada ao pronto-atendimento com febre e vômitos há dois dias, sendo inicialmente liberada com orientações e sintomáticos. Retornou no dia seguinte devido à persistência da febre. No exame físico, apresentava-se em mau estado geral, gemente, com taquipneia (76 irpm), tiragens subcostais e intercostais, retração de fúrcula, batimento de asa de nariz e rebaixamento do nível de consciência. A percussão torácica revelou submacicez no terço superior do hemitórax direito. Radiografia de tórax mostrou hipotransparência difusa no hemitórax direito e presença de pneumatoceles no lobo superior direito. Tomografia computadorizada sem contraste evidenciou áreas de necrose pulmonar. Diante desse quadro, a melhor conduta antimicrobiana inicial é:","options":{"A":"Amoxicilina oral, associada a cuidados domiciliares e reavaliação ambulatorial.","B":"Oxacilina intravenosa associada a gentamicina, em enfermaria pediátrica.","C":"Ceftriaxona intravenosa, mantendo observação hospitalar.","D":"Vancomicina associada a cefepime, com suporte avançado de vida, internação em UTI e intubação orotraqueal, se necessário.","E":"Azitromicina oral associada a antipiréticos e vigilância clínica em casa."},"answer":"D","assunto":"Pneumologia Pediátrica","topico":"Pneumonias/Broncopneumonias (BCP) na Infância","subtopico":"Tratamento Complicações"},{"id":"uepa-2026-100","number":100,"area":"Pediatria","source":"UEPA 2026","examId":"uepa-2026","examName":"UEPA Acesso Direto: 2026","stem":"De acordo com a Organização Mundial da Saúde (OMS), alguns sinais indicam a necessidade de reavaliação médica imediata em casos de diarreia, especialmente na população pediátrica. Esses sinais de alerta ajudam a identificar quadros potencialmente graves que exigem intervenções precoces para evitar complicações como desidratação severa, sepse ou desnutrição aguda. Com base nas recomendações da OMS, assinale a alternativa que apresenta um sinal de alerta em crianças com diarreia aguda.","options":{"A":"Melhora progressiva do apetite e redução das evacuações.","B":"Diarreia com duração de 2 dias, sem vômitos ou febre.","C":"Vômitos repetidos e presença de sangue nas fezes.","D":"Frequência urinária preservada e boa aceitação de líquidos.","E":"Diarreia autolimitada com duração inferior a 48 horas."},"answer":"C","assunto":"Gastrologia Pediátrica","topico":"Diarreia Aguda ","subtopico":"Manejo da hidratação"},{"id":"uepa-2025-001","number":1,"area":"Psiquiatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 24 anos, comparece a UBS pois vem apresentando quadro de dispneia leve aos esforços, faz uso de cigarro eletrônico, há três anos, com dose de 15 mg de nicotina em 3 a 4 dias, refere utilizar mais pela noite quando está ansioso, veio a consulta pois pretende parar de fumar. A terapêutica instituída, neste caso, deve ser:","options":{"A":"orientar diminuir a nicotina de 15 mg para 5 mg por sete dias, e progressivamente diminuir para 1,5 mg em vinte dias e depois 0,5 mg em trinta dias.","B":"indicar terapia cognitivo comportamental e bupropiona 150 mg, 1 vez ao dia por três dias, depois iniciar 150 mg 2x ao dia por 12 semanas.","C":"iniciar bupropiona 150 mg, duas vezes ao dia por quatro semanas, sendo reavaliado para iniciar a terapia cognitivo comportamental.","D":"iniciar terapia cognitivo comportamental e em quatro a seis semanas, reavaliar para iniciar bupropiona 150 mg, 1 vez ao dia.","E":"acolher a demanda do paciente e indicar goma de mascar de nicotina ou adesivo de nicotina, reavalia-lo em quatro semanas."},"answer":"B","assunto":"Dependência Química","topico":"Tabaco"},{"id":"uepa-2025-002","number":2,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Como médico em uma UBS, você realiza uma visita domiciliar de um paciente de 69 anos, acamado por conta de quadro demencial, com trombose venosa profunda em membro inferior esquerdo, necessita de múltiplas visitas para orientação da família sobre os cuidados gerais, otimização de anticoagulação e controle do quadro álgico. Sendo assim, a melhor indicação de cuidado, neste caso, é:","options":{"A":"indicar internação hospitalar, possível indicação de leito de cuidados paliativos, para acolhimento da família e controle da dor do paciente.","B":"indicar internação hospitalar, observando a necessidade da anticoagulação plena e otimização da analgesia, de forma a ser abordado pela equipe multidisciplinar de forma intensiva.","C":"Atenção Domiciliar 3 (AD3), realizada pelo programa Melhor em Casa, já que será necessária a participação da equipe multidisciplinar associada ao NASF.","D":"atenção Domiciliar 2 (AD2), realizada pelo Programa Melhor em Casa, indicando maior frequência das visitas e otimização da assistência.","E":"atenção Domiciliar 1 (AD1), realizada pelo Programa Melhor em Casa, como suporte multiprofissional, para melhor acolher família e paciente."},"answer":"D","assunto":"Sistema Único de Saúde (SUS)","topico":"Principais marcos legais do SUS","subtopico":"Outras normativas do SUS e da Saúde em geral"},{"id":"uepa-2025-003","number":3,"area":"Infectologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 26 anos comparece a UBS em consulta, trazendo resultados de exames de rastreios para idade: vida sexual ativa, mais de três parceiros sexuais nos últimos seis meses, uso irregular de preservativos, traz os seguintes exames: Hemograma sem alterações, VDRL: 1:32, Anti-HIV 1 e 2 não reagente, Anti-HCV: não reagente, HBsAg: negativo, Anti-HBs: positivo, HBcAg: negativo, Anti-HBc: negativo, Anti-HTLV: negativo. Neste caso, além de oferecer preservativos e orientar sobre o uso e explicar os riscos deve-se:","options":{"A":"solicitar teste treponemico e indicar PREP.","B":"indicar vacinação para Hepatite B.","C":"indicar o uso de PREP.","D":"indicar Penicilina benzatina 1.2milhoes UI IM.","E":"indicar Penicilina benzatina 2.4 milhões UI IM."},"answer":null,"assunto":"Infecções sexualmente transmissíveis","topico":"Sífilis","annulled":true},{"id":"uepa-2025-004","number":4,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Em atendimento na UBS, você atende um paciente no quinto dia pós operatório de colecistectomia aberta, apresenta um pouco de secreção serosa na incisão de Kocher, sem demais sinais e sintomas. O paciente ficou preocupado, relembrando as fases da cicatrização. A fase que o paciente se encontra, e conduta indicada são:","options":{"A":"proliferativa (fibroplasia); retornar ao cirurgião geral.","B":"reparativa (remodelação); prescrever colagenase 0,6U/g.","C":"exudativa (inflamatória); precrever Nimesulida 100mg de 12/12 horas.","D":"exudativa (inflamatória); indicar higienização com água e sabão.","E":"proliferativa (fibroplasia); prescrever Cefalexina 500 mg 8/8horas."},"answer":"D","assunto":"Cicatrização de Feridas","topico":"Fases da Cicatrização ","subtopico":"Fase Inflamatória"},{"id":"uepa-2025-005","number":5,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Para instituir um teste de rastreio de autismo na população infantil em nível nacional, deve-se observar a capacidade do teste:","options":{"A":"sensibilidade, já que buscamos os de fato autistas.","B":"especificidade, já que buscamos os de fato não autistas.","C":"especificidade, já que buscamos os de fato autistas.","D":"sensibilidade, já que buscamos os de fato não autistas.","E":"acurácia, elevada sensibilidade e especificidade."},"answer":"E","assunto":"Epidemiologia","topico":"Testes Diagnósticos","subtopico":"Medidas de Desempenho de Testes Diagnósticos (ou Medidas de Performance de Testes Diagnósticos)"},{"id":"uepa-2025-006","number":6,"area":"Dermatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente atendido na UBS com lesão com a seguinte descrição: “... Placa única de sete centímetros em ombro, com bordas elevadas, nodulações de coloração avermelhada, sem descamação, centro avermelhado...” Neste caso a hipótese diagnóstica e conduta adequada são:","options":{"A":"Pitiríase rosea de Gilbert, dermatoscopia com dermatoscópio.","B":"Psoríase, curetagem de Brocq buscando sinal de Aupstz.","C":"Pitiríase versicolor, realizar estiramento da pele visando o sinal de Zileri.","D":"Carcinoma espinocelular, dermatoscopia com dermatoscópio.","E":"Hanseníase, teste de sensibilidade tátil, dolorosa e térmica."},"answer":"E","assunto":"Hanseníase","topico":"Exame dermatoneurológico"},{"id":"uepa-2025-007","number":7,"area":"Dermatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Criança de três anos, vem acompanhada da mãe, com quadro de prurido generalizado iniciado há dois dias que piora pela noite, com cefaleia, febre e sinais de desidratação moderada. Baseado neste caso, deve-se:","options":{"A":"investigar possível caso de violência física ou sexual contra criança.","B":"buscar doenças familiares de origem materna, doenças mitocondriais.","C":"investigar se realizou o teste do pézinho, principalmente hemoglobinopatias.","D":"buscar outras pessoas com quadro parecido na casa, vizinhança e escola.","E":"investigar se houve vacinações realizadas anteriores aos dois anos de idade."},"answer":"D","assunto":"Dermatoses infecciosas","topico":"Doenças parasitárias"},{"id":"uepa-2025-008","number":8,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"O Ministério da Saúde, publicou em 21 de setembro de 2017 a portaria Nº 2.436 do Ministério da Saúde que aprova a política nacional de Atenção Básica. No que se refere as responsabilidades das esferas de governo previstas nessa portaria assinale a alternativa correta.","options":{"A":"Definir estratégias de institucionalização da avaliação da Atenção Básica é de competência municipal.","B":"Garantir acesso ao apoio diagnóstico e laboratorial necessário ao cuidado resolutivo da população é de competência estadual.","C":"Divulgar periodicamente os relatórios de indicadores da Atenção Básica é de competência do Ministério da Saúde.","D":"Fortalecer a Estratégia Saúde da Família na rede de serviços é de competência da secretaria municipal.","E":"Garantir espaços para a participação da comunidade no exercício do controle social é de competência estadual."},"answer":"A","assunto":"Sistema Único de Saúde (SUS)","topico":"Atenção Primária à Saúde (APS) no Brasil","subtopico":"Política Nacional de Atenção Básica (PNAB)"},{"id":"uepa-2025-009","number":9,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere aos Núcleos Ampliados de Saúde da Família e Atenção Básica (Nasf-AB) assinale a alternativa correta.","options":{"A":"São serviços com unidades físicas independentes ou especiais.","B":"Possuem livre acesso para atendimento individual ou coletivo.","C":"Gerenciar o planejamento da rede de atenção.","D":"São formados por categorias de profissionais definidas pelo gestor estadual.","E":"Atuam de maneira complementar às equipes que atuam na atenção básica."},"answer":"E","assunto":"Sistema Único de Saúde (SUS)","topico":"Atenção Primária à Saúde (APS) no Brasil","subtopico":"Política Nacional de Atenção Básica (PNAB)"},{"id":"uepa-2025-010","number":10,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere aos itens necessários à implantação da Estratégia de Agentes Comunitários de Saúde (EACS) assinale a alternativa correta.","options":{"A":"A carga horária dos ACS é de 20 horas semanais.","B":"A equipe tem na sua composição pelo menos um médico supervisor.","C":"A população de cada microárea de responsabilidade de cada ACS é de até 750 pessoas.","D":"A atividade do ACS é baseada a partir das metas previstas pela secretaria de saúde estadual.","E":"A equipe atua independentemente da existência de uma Unidade Básica de Saúde (UBS)."},"answer":"C","assunto":"Sistema Único de Saúde (SUS)","topico":"Atenção Primária à Saúde (APS) no Brasil","subtopico":"Política Nacional de Atenção Básica (PNAB)"},{"id":"uepa-2025-011","number":11,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere a Atenção básica para populações específicas assinale a alternativa correta.","options":{"A":"A Equipe de saúde da família ribeirinha (eSFR) deve realizar o atendimento para as comunidades distantes da UBS de referência no mínimo a cada 45 (quarenta e cinco)dias.","B":"A Equipe de Consultório de Rua (eCR) devem atuar em horário adequado as demandas da população de rua , podendo ocorrer em período diurno e/ou noturno.","C":"Na Equipe de saúde da família ribeirinha (eSFR), em área de grande dispersão populacional é previsto a inclusão na equipe de até 30 (trinta) agentes comunitários de saúde.","D":"Na Equipe de Consultório de Rua (eCR) o agente social , quando existir será considerado equivalente ao profissional de nível superior com a função de garantir a defesa da população de rua.","E":"Na Equipe de saúde da família ribeirinha (eSFR) a operacionalização das ações contará com o apoio de até 2 (duas) embarcações de pequeno porte exclusivas para o deslocamento dos profissionais da equipe."},"answer":"B","assunto":"Sistema Único de Saúde (SUS)","topico":"Políticas de Saúde do Sistema Único de Saúde","subtopico":"Políticas de Saúde para Populações Específicas"},{"id":"uepa-2025-012","number":12,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere aos estudos epidemiológicos, assinale a alternativa INCORRETA.","options":{"A":"O ensaio clínico randomizado é aquele na qual os indivíduos são alocados aleatoriamente.","B":"O ecológico tem como unidade de análise indivíduos e o ambiente.","C":"O de coorte é aquele que um grupo de pessoas é identificado e a informação pertinente sobre a exposição de interesse é coletada.","D":"O de caso-controle é uma investigação que parte do efeito para elucidar as causas.","E":"O estudo transversal é aquele na qual relação exposição-doença é examinada, em uma dada população, em um particular momento."},"answer":"B","assunto":"Epidemiologia","topico":"Estudos Epidemiológicos","subtopico":"Tipos de Estudos Epidemiológicos"},{"id":"uepa-2025-013","number":13,"area":"Medicina Preventiva","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere a saúde ocupacional assinale a alternativa correta.","options":{"A":"A doença profissional é aquela adquirida ou desencadeada em função de condições especiais em que o trabalho é realizado sendo necessário a comprovação do nexo causal.","B":"O acidente de trabalho típico é a aquele que ocorre com o trabalhador no local do trabalho ou no percurso do mesmo de sua residência /local de trabalho/residência.","C":"A ofensa física intencional de terceiros por motivos de disputa relacionada ao trabalho que ocorram no local e horário do trabalho é um evento que se equipara ao acidente de trabalho.","D":"A Perda auditiva induzida pelo ruído, que é relacionada ao trabalho, é maior nos primeiros 5 anos de exposição, podendo ser ou não neurossensorial.","E":"A Comunicação de Acidente de Trabalho (CAT) deve ser preenchida pela empresa da vítima do acidente no prazo de até cinco dias úteis após o ocorrido."},"answer":"C","assunto":"Saúde do Trabalhador","topico":"Acidente de trabalho","subtopico":"Conceitos gerais"},{"id":"uepa-2025-014","number":14,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere a administração de vacinas assinale a alternativa correta.","options":{"A":"As vacinas de vírus vivos quando não são administradas simultaneamente devem ser realizadas em um intervalo de 15 dias entre elas.","B":"A vacina da febre amarela pode ser administrada simultaneamente com a pneumocócica 10 valente.","C":"A taxa de soro conversão é superior no caso de administração das vacinas de maneira isolada.","D":"A vacina inativada ou toxóide podem ser utilizados simultaneamente com imunoglobulinas.","E":"A aplicação de vacina após transfusão de sangue total deve ser realizada após o intervalo de 30 dias."},"answer":"D","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","subtopico":"Coadministração de vacinas"},{"id":"uepa-2025-015","number":15,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"É uma vacina de aplicação subcutânea:","options":{"A":"BCG","B":"Febre amarela","C":"Hepatite B","D":"Haemophilus Influenza B","E":"Poliomielite Inativada (VIP)"},"answer":"B","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","subtopico":"Vacina contra febre amarela"},{"id":"uepa-2025-016","number":16,"area":"Psiquiatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere aos sinais e sintomas do TDAH (Transtorno de Déficit de Atenção/Hiperatividade) estabelecidas no DSM-5 assinale a alternativa correta.","options":{"A":"Na idade pré-escolar a desatenção é o sintoma mais frequente.","B":"Para o diagnóstico em adultos são necessários pelo menos sete sintomas de desatenção.","C":"O tempo de persistência dos sintomas deve ser de pelo menos 12 meses para ser considerado no diagnóstico.","D":"A ocorrência de sintomas de desatenção ou hiperatividade em apenas um ambiente confirma o diagnóstico.","E":"A atitude de usar coisas de outras pessoas sem pedir ou receber permissão é um dos sintomas da hiperatividade."},"answer":"E","assunto":"Psiquiatria Infantil","topico":"Transtorno do Déficit de Atenção e Hiperatividade (TDAH)"},{"id":"uepa-2025-017","number":17,"area":"Infectologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Diante de um paciente com queixa de corrimento uretral com bacterioscopia cujo resultado revelou diplococos Gram-negativos intracelulares, a conduta terapêutica de acordo com o Fluxograma de corrimento uretral,é:","options":{"A":"tratar clamídia e gonorreia.","B":"tratar só clamídia.","C":"tratar só gonorreia.","D":"tratar tricomoníase.","E":"tratar Clamídia, gonorreia e tricomoníase."},"answer":"A","assunto":"Infecções sexualmente transmissíveis","topico":"Uretrites"},{"id":"uepa-2025-018","number":18,"area":"Infectologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Diante de um paciente com sífilis primária o esquema de penicilina benzatina recomendado é:","options":{"A":"2,4 milhões de UI em dose única.","B":"2,4 milhões de UI, duas doses com intervalo de 3 dias.","C":"2,4 milhões de UI, três doses com intervalo de 3 dias.","D":"2,4 milhões de UI, quatro doses com intervalo de 3 dias.","E":"2,4 milhões de UI, cinco doses com intervalo de 3 dias."},"answer":"A","assunto":"Infecções sexualmente transmissíveis","topico":"Sífilis"},{"id":"uepa-2025-019","number":19,"area":"Dermatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere ao diagnóstico clínico e laboratorial da hanseníase, assinale a alternativa correta.","options":{"A":"A baciloscopia é positiva na forma tuberculóide.","B":"A histopatologia com granulomas é observada na forma indeterminada.","C":"As lesões foveolares são observadas na forma tuberculóide.","D":"A pesquisa da sensibilidade tátil deve ser realizada antes da dolorosa.","E":"As globias são observadas na baciloscopia da forma virchowiana."},"answer":"E","assunto":"Hanseníase","topico":"Diagnóstico"},{"id":"uepa-2025-020","number":20,"area":"Dermatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No que se refere as reações hansênicas assinale a alternativa correta.","options":{"A":"Os pacientes que cursem com eritema nodoso hansênico após o término do tratamento da hanseníase devem retomar o esquema da PQT (Polioquimoterapia).","B":"As coinfecções , o stress , focos de infecção dentária estão entre os fatores precipitantes das reações hansênicas.","C":"A do tipo II caracteriza-se pelo surgimento de novas lesões, agravamento das lesões anteriores e comprometimento de nervos periféricos.","D":"O tratamento de escolha para reações hansênicas do tipo eritema nodoso em pacientes do sexo feminino é a talidomida.","E":"A reação reversa ocorre em pacientes da forma tuberculóide sendo uma reação de hipersensibilidade associada a dapsona."},"answer":"B","assunto":"Hanseníase","topico":"Estados reacionais"},{"id":"uepa-2025-021","number":21,"area":"Cardiologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A hipertensão arterial não controlada atinge uma parcela considerável da população hipertensa, em muitas situações o uso concomitante de outros fármacos, que potencialmente podem elevar os níveis pressóricos pode ter relação com essa falta de controle. Entre as alternativas abaixo o grupo de drogas que pode aumentar a pressão arterial é:","options":{"A":"Eritropoetina – Ciclosporina – Bevacizumabe – Ritalina.","B":"Tracolimo – Omeprazol – Amilorida – Sildenafila - Dietilpropiona.","C":"Olpasiran – Tapentadol – Ivabradina - Duloxetina.","D":"Vonoprazana – Contraceptivos orais - Pirfenidona.","E":"Tansulosina – Ticagrelor – Semaglutida – Tapentadol - Omeprazol."},"answer":"A","assunto":"Hipertensão Arterial Sistêmica (HAS)","topico":"Hipertensão arterial complicada"},{"id":"uepa-2025-022","number":22,"area":"Endocrinologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Em relação ao tratamento do diabetes tipo 2 com análogos do GLP-1 e inibidores de SGLT2, assinale a alternativa INCORRETA.","options":{"A":"Um dos efeitos colaterais mais comuns dos inibidores de SGLT2 é a ocorrência de infecções genitais, como vulvovaginites e balanites.","B":"Análogos do GLP-1 são frequentemente associados a efeitos colaterais gastrointestinais, como náuseas e vômitos, o que pode limitar sua adesão em alguns pacientes.","C":"Inibidores de SGLT2 promovem perda de glicose pela urina, o que pode resultar em um risco aumentado de cetoacidose diabética, mesmo em pacientes com diabetes tipo 2.","D":"Os análogos do GLP-1 são contraindicados em pacientes com histórico de insuficiência cardíaca, devido ao aumento do risco de piora da função cardíaca.","E":"Análogos do GLP-1 devem ser temporariamente suspensos antes de procedimentos que envolvem anestesia ou sedação, devido ao risco de broncoaspiração causado pelo esvaziamento gástrico retardado."},"answer":"D","assunto":"Diabetes ","topico":"Diabetes Mellitus tipo 2 (DM 2)"},{"id":"uepa-2025-023","number":23,"area":"Nefrologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Com relação ao mecanismo de ação da furosemida, é correto afirmar que:","options":{"A":"a intensidade da sua atuação na alça de Henle não depende pela filtração glomerular.","B":"em dose máxima pode levar à excreção de até 20 a 25 por cento do sódio filtrado.","C":"seu mecanismo de ação também envolve a inibição da anidrase carbônica na porção espessa da alça de Henle.","D":"promove a reabsorção de cálcio podendo levar a hipercalcemia.","E":"tem ação diurética por bloqueio da reabsorção de água, sódio e cloro no néfron distal."},"answer":"B","assunto":"Distúrbios do potássio ","topico":"Diuréticos"},{"id":"uepa-2025-024","number":24,"area":"Cardiologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A manobra propedêutica que pode ser utilizada para diferenciação do sopro sistólico da regurgitação tricúspide do sopro sistólico da insuficiência mitral é:","options":{"A":"Manobra de Rivero-Carvalho.","B":"Decúbito lateral esquerdo.","C":"Manobra de Valsalva.","D":"Exercício isométrico.","E":"Manobra de Muller."},"answer":"A","assunto":"Valvopatias","topico":"Semiologia cardiaca "},{"id":"uepa-2025-025","number":25,"area":"Endocrinologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"O caso clínico em que o paciente tem indicação de tratamento para osteoporose é:","options":{"A":"mulher, 55 anos, densitometria óssea com T-score de 0,5 e níveis de vitamina D abaixo de 20 ng/mL. Seu médico recomenda a reposição de vitamina D e drogas antirreabsortivas, para tratamento para osteoporose devido a sua idade.","B":"homem, 60 anos, tem densitometria com densidade mineral óssea normal, mas apresenta níveis de vitamina D de 18 ng/mL e PTH ligeiramente elevado. Tem histórico familiar de osteoporose. Seu médico sugere a reposição de vitamina D e uso de bifosfonatos antes de reavaliar o PTH após a normalização da vitamina D.","C":"mulher, 52 anos, está em uso de corticoides há 5 anos devido artrite reumatoide e apresenta densitometria óssea com T-score de -2,5. Seu médico indica o uso de drogas antirreabsortivas para o tratamento da osteoporose, além da reposição de vitamina D e cálcio.","D":"homem, 59 anos, tem DMO com T-score de -2,0 e histórico de fratura de quadril há 3 anos. Ele apresenta insuficiência renal crônica e está em programa de diálise, o que não contraindica o uso de bifosfonatos para o tratamento da osteoporose.","E":"mulher, 48 anos, já na pós menopausa em uso de terapia de reposição hormonal, apresenta densitometria com T-score de -1,2 e não teve histórico de fraturas. O médico sugere que ela deve manter uma dieta rica em cálcio e uso de vitamina D, além de iniciar o uso de antirreabsortivos."},"answer":"C","assunto":"Metabolismo Ósseo e Mineral","topico":"Distúrbios do remodelamento ósseo"},{"id":"uepa-2025-026","number":26,"area":"Reumatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Uma mulher de 49 anos de idade foi internada por causa de glomerulonefrite rapidamente progressiva. No exame físico, a pressão arterial era 180/90 mmHg, o pulso de 90 bpm, a temperatura de 37,7°C; a palpação do abdome era discretamente dolorosa no quadrante superior direito, sem descompressão positiva ou massas palpáveis; o restante do exame era normal. As fezes eram escuras com sangue oculto positivo. O nível de C3 era 35mg/dl (normal, 86 – 184) e o de C4 < 2 mg/dl (normal 16 – 38). Entre as situações abaixo o diagnóstico mais provável é:","options":{"A":"Granulomatose com poliangiite.","B":"Crioglobulinemia.","C":"Granulomatose eosinofílica com poliangiite.","D":"Nefropatia por IgA.","E":"Glomerulonefrite aguda pós-estreptocócica."},"answer":"B","assunto":"Vasculites","topico":"Vasculites de pequenos vasos"},{"id":"uepa-2025-027","number":27,"area":"Neurologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Uma mulher de 64 anos que tem apresentado episódios recorrentes de tonturas. Nesses episódios, o ambiente subitamente parece rodar e ela tem que se segurar em alguma coisa para se firmar. No exame clínico é identificado um nistagmo do olhar conjugado para a direita e esquerda, e um nistagmo vertical. A marcha está ligeiramente atáxica com dificuldade de caminhar em linha reta, desvio lateral, falta de equilíbrio, base de apoio alargada. De acordo com esses achados o diagnóstico mais provável é:","options":{"A":"Síndrome de Arnold-Chiari.","B":"Vertigem de origem central.","C":"Doença de Ménière.","D":"Neurinoma do acústico.","E":"Síndrome de Ramsay Hunt."},"answer":"B","assunto":"Neurologia Vestibular","topico":"Síndromes Vestibulares Centrais"},{"id":"uepa-2025-028","number":28,"area":"Hematologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Na avaliação laboratorial de pacientes com trombose venosa profunda para o diagnóstico de trombofilia todos os exames a seguir podem ser realizados enquanto o paciente está usando heparina, EXCETO:","options":{"A":"Nível de proteína C","B":"Nível de proteína S","C":"Nível de antitrombina III","D":"Mutação do fator V","E":"Anticorpos antifosfolipídeos"},"answer":"C","assunto":"Hemostasia","topico":"Trombofilia"},{"id":"uepa-2025-029","number":29,"area":"Infectologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Um trabalhador rural de 65 anos de idade com quadro demencial leve apresenta títulos séricos de VDRL de 1:16 e pesquisa de Anticorpo Antitreponêmico Fluorescente (FTA) positivo. O restante de sua avaliação é negativo, incluindo análise do LCR com proteína e glicose normais, menos de 6 leucócitos e VDRL no líquor negativo. Não há relato de tratamento prévio para sífilis ou alergia a antibióticos. O tratamento mais adequado é:","options":{"A":"Penicilina G cristalina, 10 milhões de unidades, IV, durante 7 dias.","B":"Penicilina procaína, 600.000 unidades/dia, IM, durante 6 dias.","C":"Penicilina benzatina, 2,4 milhões de unidades, IM, uma vez por semana (3 doses).","D":"Ceftriaxona 2g/dia, IV dose única.","E":"Azitromicina 1g/dia, IV durante 7 dias."},"answer":"C","assunto":"Infecções sexualmente transmissíveis","topico":"Sífilis"},{"id":"uepa-2025-030","number":30,"area":"Gastroenterologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Um empresário da construção civil de 63 anos relata perda progressiva de peso não intencional de 9 quilos durante os últimos 10 meses. Refere saciedade precoce e náuseas. Refere fezes escurecidas com odor fétido. A endoscopia digestiva alta revelou adenocarcinoma gástrico. A condição que NÃO é considerado um fator de risco para adenocarcinoma gástrico é:","options":{"A":"uso prolongado de inibidores de bomba de prótons.","B":"Pólipo adenomatoso gástrico.","C":"Gastrite atrófica metaplásica.","D":"Infecção por Helicobacter pylori.","E":"Cirurgia gástrica tipo Billroth II para úlcera péptica."},"answer":"A","assunto":"Neoplasias do Sistema Digestivo","topico":"Neoplasias do Estômago"},{"id":"uepa-2025-031","number":31,"area":"Endocrinologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Entre os casos abaixo a realização de Punção Aspirativa por Agulha Fina (PAAF) para investigação do nódulo tireoidiano está corretamente indicada para:","options":{"A":"mulher de 32 anos, com hipotireoidismo subclínico e nódulo tireoidiano de 0,8 cm, sem características suspeitas ao ultrassom.","B":"homem de 50 anos com histórico familiar de câncer de tireoide, apresentando um nódulo de 1,2cm no lobo esquerdo da tireoide, que exibe microcalcificações e margens irregulares ao ultrassom.","C":"mulher de 40 anos com hipertireoidismo e nódulo tireoidiano de 0,9 cm com vascularização central, mas sem outras características suspeitas ao ultrassom.","D":"homem de 35 anos com nódulo tireoidiano de 0,9 cm no lobo direito, com ecogenicidade aumentada e bordas regulares ao ultrassom. Sem história familiar de câncer de tireoide.","E":"mulher de 29 anos, com hipotireoidismo e nódulo tireoidiano misto de 1,5cm, de contornos regulares e sem sinais de malignidade ao ultrassom."},"answer":"B","assunto":"Tireoide","topico":"Manejo dos Nódulos Tireoidianos"},{"id":"uepa-2025-032","number":32,"area":"Gastroenterologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Um advogado de 62 anos procura o pronto atendimento com história de dor abdominal na fossa ilíaca esquerda, fezes amolecidas e febre. O exame físico revela sinais normais, temperatura axilar de 38.7ºC, dor a palpação e descompressão no quadrante inferior do abdome, mas não foi possível palpar massas definidas. O hemograma revela leucocitose de 17.000/mm3 com 70% de neutrófilos. Todos os procedimentos são adequados na abordagem inicial, EXCETO:","options":{"A":"tratamento antimicrobiano endovenoso com cefalosporina de 3ª geração + metronidazol.","B":"tomografia do abdome.","C":"parecer cirúrgico.","D":"radiografias abdominal deitado e em pé e do tórax.","E":"colonoscopia."},"answer":"E","assunto":"Intestinos","topico":"Doença Diverticular"},{"id":"uepa-2025-033","number":33,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Uma mulher de 35 anos de idade, é admitida na unidade de terapia intensiva com taquicardia sinusal, taquipneia, hipotensão arterial e temperatura axilar de 39.5ºC após colecistectomia videolaparoscópica eletiva. No exame físico é notável a rigidez muscular generalizada. No eletro presença de ondas T pontiagudas, desaparecimento das ondas P, alargamento do QRS e raras extrassístoles ventriculares. O medicamento que deve ser administrado imediatamente é:","options":{"A":"Noradrenalina.","B":"Paracetamol.","C":"Dantrolene.","D":"Hidrocotisona.","E":"Aspirina."},"answer":"C","assunto":"Princípios da Anestesiologia","topico":"Agentes Anestésicos","subtopico":"Agentes Inalatórios"},{"id":"uepa-2025-034","number":34,"area":"Reumatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Um universitário de 19 anos apresentou-se ao pronto atendimento com história de vários episódios de dor abdominal associado a edema dos lábios e da língua induzidos por estresse e esforço físico tende a apresentar baixos níveis funcionais de proteínas:","options":{"A":"ECA","B":"IgA","C":"C8","D":"Inibidor de C1 esterase","E":"Triptase"},"answer":"D","assunto":"Introdução à Reumatologia","topico":"Bases imunológicas da Reumatologia"},{"id":"uepa-2025-035","number":35,"area":"Endocrinologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Uma mulher de 48 anos com câncer de mama em espera para iniciar tratamento quimioterápico chega ao pronto socorro com quadro de confusão mental, constipação intestinal, câimbras, dores ósseas, poliúria, polidipsia, bradicardia e encurtamento do QT no ECG. O diagnóstico mais provável é:","options":{"A":"Hiperpotassemia.","B":"Hipercalcemia.","C":"Síndrome de lise tumoral.","D":"Coma hiperosmolar não cetótico.","E":"Síndrome da secreção inapropriada de ADH - SIADH."},"answer":"B","assunto":"Metabolismo Ósseo e Mineral","topico":"Distúrbios do cálcio"},{"id":"uepa-2025-036","number":36,"area":"Psiquiatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Um homem de 55 anos, portador de carcinoma pulmonar com metástases ósseas, faz uso de analgésico potente cujo nome não sabe informar para controle de dor de forte intensidade. Evoluindo com sonolência, sendo levado à emergência do hospital. Ao exame, apresenta-se torporoso, bradipneico e com pupilas mióticas. A conduta imediata neste caso é:","options":{"A":"Atropina.","B":"Naloxone.","C":"Flumazenil.","D":"Expansão volêmica.","E":"Hidrocortisona."},"answer":"B","assunto":"Intoxicações Exógenas","topico":"Síndrome Narcótica"},{"id":"uepa-2025-037","number":37,"area":"Nefrologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Um paciente de 45 anos, com antecedente de síndrome de Sjögrem procura o pronto atendimento queixando-se de parestesias e cansaço fácil. Na admissão a pressão arterial era 120 x 60mmHg, ausculta cardíaca e pulmonar sem alterações, sem sinais neurológicos focais. Tem os resultados laboratoriais realizados há 2 dias: sódio sérico-138 mEq/L; potássio sérico-3.0 mEq/L; cloreto sérico-112 mEq/L; HCO3-15 mEq/L, pH arterial-7.25 e fósforo sérico normal. No exame de urina pH-5.8; sódio-15 mEq/L; potássio-10 mEq/L e cloreto de 12 mEg/L. O diagnóstico mais provável, neste caso, é:","options":{"A":"Acidose tubular renal tipo I","B":"Acidose tubular renal tipo II","C":"Síndrome de Gitelman","D":"Acidose tubular renal tipo III","E":"Síndrome de Liddle"},"answer":"A","assunto":"Túbulo-Interstício","topico":"Tubulopatias"},{"id":"uepa-2025-038","number":38,"area":"Nefrologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Uma paciente de 51 anos, com histórico de hipertensão arterial há 5 anos, bem controlada com Losartana 100 mg/dia e anlolodipina 10mg/dia, além de diabetes tipo 2 em uso de metformina 1g/dia, apresentou hipertensão arterial de difícil controle nas últimas semanas, acompanhada de cãibras frequentes nas pernas, tremores e cansaço. Ela relata que nos últimos 2 meses faz uso diário de cerca de 15 balas com adoçante para controlar a vontade de consumir doces. Refere ainda o uso de naproxeno 250mg a cada 12 horas nos últimos 3 dias devido lombalgia. Exames revelam potássio de 2,5 mEq/L. A mais provável causa da condição atual da paciente é:","options":{"A":"uso de AINES.","B":"o uso de Losartana pode estar contribuindo para a hipocalemia e sintomas da paciente.","C":"hiperaldosteronismo primário.","D":"efeito do alcaçuz (glicirrizina) presente no adoçante.","E":"uso de Anlodipina."},"answer":"D","assunto":"Distúrbios do potássio ","topico":"Hipocalemia"},{"id":"uepa-2025-039","number":39,"area":"Reumatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Diversas medicações utilizadas com os mais diferentes intuitos podem causar efeitos adversos. Assinale a alternativa que NÃO apresenta uma relação entre uma medicação e um efeito adverso.","options":{"A":"Quinolona e ruptura do tendão de Aquiles.","B":"Losartana e crise de gota.","C":"Linezolida e neuropatia óptica.","D":"Propiltiouracil e vasculite.","E":"Paroxetina e hiponatremia."},"answer":"B","assunto":"Artropatias inflamatórias","topico":"Artrites microcristalinas"},{"id":"uepa-2025-040","number":40,"area":"Hematologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Trombocitose refere-se a um aumento da contagem de plaquetas ≥ 450.000mm. Todas as seguintes alternativas estão associadas a trombocitose, EXCETO:","options":{"A":"Perda aguda de sangue.","B":"Pós-esplenectomia.","C":"Síndrome mielodisplásicas a deleção do cromossomo 5 ( síndrome 5q-).","D":"Trombocitemia essencial.","E":"Anemia perniciosa."},"answer":"E","assunto":"Mielodisplasias e mieloproliferações: outras alterações da medula óssea","topico":"Doenças mieloproliferativas crônicas"},{"id":"uepa-2025-041","number":41,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A cricotireoidostomia por punção pode ser realizada em pacientes politraumatizados para manter o paciente adequadamente oxigenado por:","options":{"A":"10 a 20 minutos.","B":"20 a 30 minutos.","C":"30 a 45 minutos.","D":"45 a 60 minutos.","E":"60 a 75 minutos."},"answer":"C","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Vias Aéreas Alternativas (Não Definitivas)"},{"id":"uepa-2025-042","number":42,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente vítima de atropelamento é atendido no pronto atendimento e no exame físico nota-se abertura ocular somente aos estímulos dolorosos / de pressão, emite palavras inapropriadas e tem flexão anormal dos membros. Assinale a alternativa que contém a correta pontuação desses achados do exame físico de acordo com a escala de coma de Glasgow.","options":{"A":"6 pontos","B":"7 pontos","C":"8 pontos","D":"9 pontos","E":"10 pontos"},"answer":"C","assunto":"Trauma","topico":"Traumatismo Cranioencefálico","subtopico":"Classificação"},{"id":"uepa-2025-043","number":43,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"No trauma torácico existem lesões com ameaça de vida imediata e ameaça potencial de vida. Assinale a alternativa que contém SOMENTE lesões com potencial ameaça à vida.","options":{"A":"Pneumotórax simples, hemotórax de 1000 mL de volume e pneumotórax aberto.","B":"Pneumotórax hipertensivo, hemotórax de 1600 mL de volume e tamponamento cardíaco.","C":"Pneumotórax hipertensivo, tamponamento cardíaco e pneumotórax aberto.","D":"Pneumotórax hipertensivo, hemotórax de 1600 mL de volume e pneumotórax aberto.","E":"Pneumotórax simples, hemotórax de 1000 mL de volume e lesão diafragmática."},"answer":"E","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Trauma Torácico"},{"id":"uepa-2025-044","number":44,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Assinale a alternativa que contém as primeiras células infiltrantes que penetram no lugar da cicatrização das feridas.","options":{"A":"Fibroblastos","B":"Polimorfonucleares","C":"Macrófagos","D":"Células endoteliais","E":"Plaquetas"},"answer":"B","assunto":"Cicatrização de Feridas","topico":"Fases da Cicatrização ","subtopico":"Fase Inflamatória"},{"id":"uepa-2025-045","number":45,"area":"Gastroenterologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Assinale a alternativa que contém a classificação correta de uma hérnia diafragmática que contém o deslocamento cefálico do fundo gástrico com o cárdia em posição normal.","options":{"A":"Tipo I","B":"Tipo II","C":"Tipo III","D":"Tipo IV","E":"Tipo V"},"answer":"B","assunto":"Esôfago","topico":"Anatomia e Alterações Estruturais"},{"id":"uepa-2025-046","number":46,"area":"Gastroenterologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Em relação ao volume das secreções gastrointestinais, assinale a alternativa correta.","options":{"A":"A secreção gástrica tem volume aproximado entre 2000 e 3000 mL em 24 horas.","B":"A secreção do intestino delgado tem volume aproximado entre 2000 e 3000 mL em 24 horas.","C":"A secreção colônica tem volume aproximado entre 1500 e 2500 mL em 24 horas.","D":"A secreção pancreática tem volume aproximado entre 1000 e 1500 mL em 24 horas.","E":"A secreção biliar tem volume aproximado entre 800 e 1500 mL em 24 horas."},"answer":"B","assunto":"Intestinos","topico":"Anatomia e Fisiologia do Intestino Delgado e Grosso"},{"id":"uepa-2025-047","number":47,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Assinale a alternativa que contém a técnica cirúrgica bariátrica, que tem o componente restritivo predominante em relação ao componente disabsortivo.","options":{"A":"Sleeve gástrico","B":"By-pass gástrico em Y de Roux","C":"Duodenal switch","D":"Banda gástrica ajustável","E":"Cirurgia de Scopinaro"},"answer":"B","assunto":"Cirurgia Bariátrica e Metabólica","topico":"Tratamento Cirúrgico da Obesidade","subtopico":"Procedimentos Cirúrgicos: Mecanismo de Ação"},{"id":"uepa-2025-048","number":48,"area":"Gastroenterologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Assinale a alternativa que contém a correta classificação de Borrmann de uma lesão gástrica ulceroinfiltrativa.","options":{"A":"Borrmann Tipo I","B":"Borrmann Tipo II","C":"Borrmann Tipo III","D":"Borrmann Tipo IV","E":"Borrmann Tipo V"},"answer":"C","assunto":"Neoplasias do Sistema Digestivo","topico":"Neoplasias do Estômago"},{"id":"uepa-2025-049","number":49,"area":"Gastroenterologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Assinale a alternativa que contém um critério de Ranson correto para pancreatite biliar.","options":{"A":"Idade acima de 50 anos.","B":"Leucócitos acima de 16.000 células/mm³.","C":"LDH acima de 400 UI/litro.","D":"Perda estimada de fluidos maior que 2 litros.","E":"Cálcio sérico menor que 10 mg/dL."},"answer":"C","assunto":"Pâncreas","topico":"Pancreatites"},{"id":"uepa-2025-050","number":50,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Assinale a alternativa que contém a mais frequente complicação após uma herniorrafia inguinal aberta segundo Sabiston.","options":{"A":"Seroma","B":"Orquite","C":"Infecção","D":"Dor crônica","E":"Recidiva"},"answer":"D","assunto":"Hérnias da Parede Abdominal","topico":"Hérnias Inguinocrurais","subtopico":"Hérnia Inguinal"},{"id":"uepa-2025-051","number":51,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Durante atendimento a um paciente politraumatizado, foi identificado desconforto respiratório moderado, FR 30, sat O2 93% em ar ambiente. No exame físico, possuía expansão torácica assimétrica e murmúrio vesicular abolido em hemitórax esquerdo. Diante da necessidade de uma drenagem torácica. O melhor local para a inserção do dreno, é:","options":{"A":"no 2° espaço intercostal na linha hemiclavicular à esquerda.","B":"no 5° espaço intercostal na linha hemiclavicular à esquerda.","C":"no 5° espaço intercostal na linha axilar média à direita.","D":"no 5° espaço intercostal na linha axilar média à esquerda.","E":"no 3° espaço intercostal na linha axilar média à direita."},"answer":"D","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Trauma Torácico"},{"id":"uepa-2025-052","number":52,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente previamente hígido, 45 anos, comparece ao pronto socorro com queixa de dor difusa abdominal, vômitos, diarreia e mal estar iniciados há 1 dia. Durante o exame físico, percebe-se a presença de uma cicatriz abdominal devido uma cirurgia eletiva prévia de colecistectomia aberta. O nome e a localização desse tipo de incisão, são:","options":{"A":"incisão de Rockey-Davis, localizada transversalmente em fossa ilíaca direita.","B":"incisão de Kocher, localizada obliquamente em região de hipocôndrio esquerdo.","C":"incisão de Mcburney, localizada obliquamente em região de fossa ilíaca direita.","D":"incisão de Kocher, localizada obliquamente em região subcostal direita.","E":"incisão mediana, localizada em epigástrio."},"answer":"D","assunto":"Vesícula e Vias Biliares","topico":"Colecistectomia","subtopico":"Colecistectomia Aberta"},{"id":"uepa-2025-053","number":53,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A internação prolongada de pacientes graves em leitos de UTI pode aumentar o risco de lesões cutâneas relacionadas ao aumento da pressão nos tecidos de certas áreas do corpo a depender da posição do paciente. O local mais frequente para o surgimento dessas lesões, relacionando com a posição do paciente, é:","options":{"A":"região sacral, quando paciente permanece mais tempo em decúbito lateral.","B":"região trocantérica, quando paciente permanece em decúbito lateral.","C":"região occipital, quando paciente se encontra em posição prona.","D":"região da face, quando paciente fica em decúbito dorsal.","E":"região do ísquio, quando paciente permanece em posição prona."},"answer":"B","assunto":"Cirurgia Plástica","topico":"Lesões Por Pressão","subtopico":"Fisiopatologia"},{"id":"uepa-2025-054","number":54,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Você atende um paciente que sofreu corte contuso em região da perna em uma barra de ferro acidentalmente. Após limpeza local, anestesia e sutura você o libera para casa com algumas orientações. Isso o faz lembrar no plantão sobre o processo de cicatrização de feridas, então discute com o outro colega plantonista sobre as etapas desse processo. Nesse sentido é correto afirmar que:","options":{"A":"a fase proliferativa, que se inicia por volta do terceiro dia após a lesão, é caracterizada pela intensa atividade fagocitária dos macrófagos, que causam o desbridamento da ferida.","B":"a fase inflamatória é a fase inicial, dura cerca de 1 a 6 dias e é responsável pelo processo de hemostasia e quimiotaxia dos leucócitos.","C":"a fase de remodelação tem início por volta da segunda semana e apresenta intensa angiogênese e início da produção de colágeno tipo I.","D":"a fase de maturação caracteriza o final do processo da cicatrização, que pode durar cerca de um ano e é responsável pela substituição de colágeno tipo I em tipo III.","E":"na fase de proliferação, as principais células presentes na ferida são os miofibroblastos que são responsáveis pelo processo de contração da ferida."},"answer":"B","assunto":"Cicatrização de Feridas","topico":"Fases da Cicatrização ","subtopico":"Fase Inflamatória"},{"id":"uepa-2025-055","number":55,"area":"Gastroenterologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A artéria retal média tem origem na:","options":{"A":"Artéria mesentérica superior.","B":"Artéria sigmoideana.","C":"Artéria ilíaca interna.","D":"Artéria mesentérica inferior.","E":"Artéria sacral média."},"answer":"C","assunto":"Intestinos","topico":"Anatomia e Fisiologia do Intestino Delgado e Grosso"},{"id":"uepa-2025-056","number":56,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"O que define a via aérea definitiva, é:","options":{"A":"catéter nasal de oxigênio.","B":"ventilação com máscara laríngea.","C":"tubo posicionado na traqueia com cuff insuflado.","D":"ventilação com máscara de oxigênio em 15l.","E":"tubo posicionado na faringe com cuff insuflado."},"answer":"C","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Via Aérea Definitiva"},{"id":"uepa-2025-057","number":57,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente, feminino, 35 anos, foi levado ao HMS pela equipe do SAMU com relato de acidente de moto X carro. Após avaliação médica foi aventada a possibilidade de trauma de uretra. sobre o trauma de uretra, assinale a alternativa correta.","options":{"A":"Em caso de trauma de uretra deve ser realizada sondagem vesical de demora por profissional experiente.","B":"A fratura de bacia é associada à lesão de uretra membranosa.","C":"A fratura de bacia está relacionada a lesão de uretra peniana.","D":"O exame ideal para diagnóstico de trauma de uretra é a cintilografia renal.","E":"O diagnóstico de trauma de uretra é feito com radiografia de pelve."},"answer":"B","assunto":"Trauma","topico":"Trauma Abdominal e Pélvico","subtopico":"Traumatismo Urológico"},{"id":"uepa-2025-058","number":58,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente vítima de acidente de trânsito moto X carreta apresentou traumatismo craniano. Na avaliação do ATLS na Escala de Coma de Glasgow (ECG) estava apresentando abertura ocular ao comando de voz, emitindo sons inaudíveis, localiza a dor na resposta motora e pupilas isofotorreagentes. A pontuação da ECG deste paciente, é:","options":{"A":"13","B":"8","C":"7","D":"9","E":"10"},"answer":null,"assunto":"Trauma","topico":"Traumatismo Cranioencefálico","subtopico":"Classificação","annulled":true},{"id":"uepa-2025-059","number":59,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Vítima de acidente moto X moto dá entrada no Hospital Municipal de Santarém apresentando ao exame físico hipertimpanismo em hemitórax direito e hipotensão. Neste caso a melhor conduta a ser tomada é:","options":{"A":"intubação orotraqueal imediata.","B":"inserção de jelco calibroso em 5º espaço intercostal ligeiramente anterior à linha axilar média do hemitórax direito.","C":"toracotomia exploradora.","D":"curativo em 3 pontos.","E":"ventilação com máscara de oxigênio em 15l."},"answer":"B","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Trauma Torácico"},{"id":"uepa-2025-060","number":60,"area":"Cirurgia Geral","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente vítima de ferimento por arma branca em hipocôndrio direito é submetido a laparotomia exploradora e durante a cirurgia foi identificado sangramento hepático grave.O cirurgião tomou a decisão de realizar uma manobra para bloquear o fluxo sanguíneo hepático. A manobra a ser realizada, neste caso, é:","options":{"A":"Mattox","B":"Pringle","C":"C-kocher","D":"Cattell","E":"Whipple"},"answer":"B","assunto":"Trauma","topico":"Trauma Abdominal e Pélvico","subtopico":"Trauma Hepático"},{"id":"uepa-2025-061","number":61,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Primigesta com 10 semanas de gravidez evolui com náuseas persistentes, 5 episódios de vômitos por dia, salivação intensa o tempo todo e sem conseguir se alimentar ou ingerir líquidos. Exame físico: desidratação leve com demais sinais vitais normais. Neste contexto a melhor terapêutica dentre as alternativas abaixo é:","options":{"A":"tratamento ambulatorial com metoclopramida.","B":"internação, hidratação, jejum inicial e sintomáticos.","C":"interrupção da gravidez.","D":"tratamento ambulatorial com Ondasetrona.","E":"tratamento ambulatorial com Meclizina."},"answer":"B","assunto":"Pré-natal","topico":"Assistência pré-natal","subtopico":"Queixas mais comuns na gestação"},{"id":"uepa-2025-062","number":62,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"O aborto espontâneo é definido como gestação intrauterina não viável até 20-22 semanas ou peso fetal de 500 g. Sobre o aborto é correto afirmar que:","options":{"A":"ameaça de aborto: aquele em que a mulher, além de sangramento vaginal abundante e cólicas uterinas, apresenta colo pérvio e feto intra-útero.","B":"aborto completo: quando há eliminação completa ou parcial do produto conceptual.","C":"aborto inevitável: a paciente apresenta sangramento vaginal, mas o orifício interno do colo uterino permanece impérvio e a vitalidade embrionária está preservada.","D":"aborto incompleto: presença apenas de saco gestacional, sem embrião, por duas semanas em paciente assintomática.","E":"aborto retido: há ausência de batimentos cardíacos fetais ou do embrião, mas não ocorre a expulsão espontânea do conteúdo intrauterino."},"answer":"E","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Sangramento primeira metade ","subtopico":"Abortamento"},{"id":"uepa-2025-063","number":63,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Primigesta com histórico de pré-eclâmpsia, 35 semanas de gestação, comparece a urgência apresentando dor abdominal de início súbito, sangramento vaginal intenso vermelho escurecido, hipersensibilidade à palpação uterina, hipertonia uterina, contorno uterino preservado, colo impérvio e bradicardia fetal. Neste contexto o diagnóstico mais provável é:","options":{"A":"Descolamento prematuro de placenta.","B":"Placenta Prévia Centro-total.","C":"Placenta Prévia Centro parcial.","D":"Trabalho de parto prematuro.","E":"Rotura uterina."},"answer":"A","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Sangramento segunda metade da gestação ","subtopico":"Descolamento prematuro de placenta (DPP)"},{"id":"uepa-2025-064","number":64,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A rotura prematura de membranas consiste na saída espontânea de líquido amniótico pela vagina na ausência de sinais de trabalho de parto, em gestações acima de 20 a 22 semanas. Sobre esta patologia é correto afirmar que:","options":{"A":"presença de infecção intrauterina indica antinbioticoterapia ampla e corticoprofilaxia para aumentar o tempo de latência.","B":"sempre que possível interromper gravidez por cesariana.","C":"a hidratação deve ser preferencialmente endovenosa.","D":"Sulfato de magnésio está recomendado como neuroprotetor conceptual se o parto for ocorrer antes de 32 semanas de gestação.","E":"deve-se realizar corticoterapia antenatal uma vez por semana até o nascimento."},"answer":"D","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Rotura prematura de membranas ovulares (RPM)","subtopico":"Conduta na RPM"},{"id":"uepa-2025-065","number":65,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Tercigesta comparece a consulta assintomática. Ao exame físico: dinâmica uterina ausente, tônus uterino normal, batimentos cardíacos fetais=145 bpm, colo uterino impérvio. No cálculo da idade gestacional apresenta-se com 42 semanas e 1 dia de gestação. Pode-se classificar esta gestação como:","options":{"A":"Prematura.","B":"Termo precoce.","C":"Termo completo.","D":"Termo tardio.","E":"Pós-termo."},"answer":"E","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Gestação pós-termo","subtopico":"Conceito"},{"id":"uepa-2025-066","number":66,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Mulher com 26 anos apresenta o seguinte resultado no exame de colpocitologia oncótica do colo de útero: “Lesão Intra-Epitelial de Baixo Grau (LSIL)”. Segundo Diretrizes brasileiras para o rastreamento do câncer do colo do útero a recomendação imediata para essa paciente deve ser:","options":{"A":"repetir o citopatológico em 12 meses.","B":"repetir o citopatológico em 6 meses.","C":"repetir o citopatológico em 3 meses.","D":"submeter-se a colposcopia imediatamente.","E":"submeter-se a biópsia imediatamente."},"answer":"B","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","subtopico":"Diretrizes para o rastreamento"},{"id":"uepa-2025-067","number":67,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Mulher de 28 anos referindo corrimento vaginal esbranquiçado, sem odor, acompanhado de prurido intenso há 5 dias, sem outras queixas. Ao exame físico: corrimento branco abundante com grumos aderidos a parede. No exame a fresco do conteúdo vaginal observa-se hifas e esporos. Com base na causa mais provável, das alternativas abaixo pode-se optar como tratamento:","options":{"A":"Metronidazol creme vaginal.","B":"Aciclovir 200 mg via oral.","C":"Clindamicina 2% creme vaginal.","D":"Secnidazol 2g via oral.","E":"Butoconazol creme vaginal."},"answer":"E","assunto":"Infecções em ginecologia","topico":"Vulvovaginites","subtopico":"Candidíase"},{"id":"uepa-2025-068","number":68,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Mulher de 27 anos, queixando-se de febre, corrimento vaginal e dor pélvica há cerca de 1 semana. Sem outras queixas. Nega atraso menstrual. Ao exame físico: dor a mobilização de colo, útero e anexos; muco cervical purulento; conteúdo vaginal amarelado, temperatura oral=38,6 0 C. Exame complementar: velocidade de hemossedimentação elevada. Neste contexto o diagnóstico mais provável é:","options":{"A":"Cervicite apenas.","B":"Vaginose.","C":"Infecção do trato urinário.","D":"Doença inflamatória pélvica.","E":"Aborto infectado."},"answer":"D","assunto":"Infecções em ginecologia","topico":"Doença Inflamatória Pélvica","subtopico":"Diagnóstico"},{"id":"uepa-2025-069","number":69,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Mulher de 25 anos comparece a consulta levando uma ultrassonografia que descreve: “ mioma FIGO 0 (zero) com 1 cm de diâmetro e mioma FIGO 2 (dois) com 3 cm de diâmetro”. Considerando a classificação da Federação Internacional de Ginecologia e Obstetrícia (FIGO) entende-se que os miomas com 1 e 3 cm podem ser descritos respectivamente como:","options":{"A":"mioma submucoso pediculado, totalmente intracavitário e mioma submucoso com componente com mais de 50% do componente intramural.","B":"mioma subseroso pediculado e mioma subseroso com menos de 40% de componente intramural.","C":"mioma submucoso pediculado, totalmente intracavitário e mioma subseroso com menos de 50% de componente intramural.","D":"mioma subseroso pediculado e mioma submucoso pediculado, totalmente intracavitário.","E":"mioma subseroso pediculado e mioma subseroso com menos de 50% de componente intramural."},"answer":"A","assunto":"Ginecologia geral","topico":"Miomatose uterina","subtopico":"Definição"},{"id":"uepa-2025-070","number":70,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"O sangramento uterino anormal é um sinal presente em diversas patologias ginecológicas, trazendo muitas vezes prejuízos sociais, econômicos e emocionais a paciente. É uma causa de sangramento uterino anormal:","options":{"A":"Hipotireoidismo.","B":"Hiperprolactinemia.","C":"Adenomiose.","D":"Sinéquias uterinas.","E":"Endometriose peritoneal."},"answer":"C","assunto":"Ginecologia endócrina","topico":"Sangramento uterino anormal","subtopico":"Etiologia"},{"id":"uepa-2025-071","number":71,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 37 anos, histerectomizada devido a história de tratamento para NIC II/III com margens livres, realizado há 3 meses. Procura o serviço de ginecologia para informações do seu seguimento. De acordo com as Diretrizes brasileiras para o rastreamento do câncer do colo do útero a recomendação correta para a paciente é:","options":{"A":"suspensão da coleta do exame citopatológico devido as margens livres.","B":"rastreamento citológico 3 anos após a histerectomia.","C":"exame citopatológico e colposcopia deveriam ter sido realizados no pós-operatório imediato.","D":"realizar exame citopatológico em 6 meses após a histerectomia, se negativo para atipias, suspender futuras coletas.","E":"realizar exame citopatológico, inicialmente, em 6 e 12 meses após a histerectomia."},"answer":"E","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","subtopico":"Diretrizes para o rastreamento"},{"id":"uepa-2025-072","number":72,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Gestante de 24 anos de idade, retorna com 8 semanas de gestação a consulta de pré-natal com resultado de exame realizado há 10 dias de citopatológico para detecção de câncer de colo do útero evidenciando Lesão Intraepitelial de baixo grau (LSIL). A conduta adequada para a gestante, de acordo com as Diretrizes brasileiras para o rastreamento do câncer do colo do útero, é:","options":{"A":"repetir o exame citopatológico durante o terceiro trimestre de gestação.","B":"realizar colposcopia imediatamente.","C":"qualquer abordagem diagnóstica deve ser feita após 3 meses do parto.","D":"realizar biópsia do colo uterino.","E":"indicar traquelectomia."},"answer":"C","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","subtopico":"Diretrizes para o rastreamento"},{"id":"uepa-2025-073","number":73,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 39 anos de idade, fez implante de Dispositivo Intrauterino (DIU) de cobre 380-A em 10/07/2011. Vem a consulta referindo corrimento vaginal. Refere disúria e dispareunia. Ao exame especular: hiperemia de paredes vaginais, fio do DIU visualizado com comprimento de cerca de 2 cm, corrimento intenso, amarelo-esverdeado, bolhoso e espumoso, acompanhado de odor fétido. Foi realizado exame a fresco com identificação de parasita flagelado com auxílio de microscopia. O diagnóstico e conduta para este caso são:","options":{"A":"manter o DIU de cobre e prescrever miconazol via vaginal. As parcerias sexuais não devem ser tratadas.","B":"manter o DIU de cobre e prescrever clindamicina via oral. As parcerias sexuais devem ser tratadas com o mesmo esquema terapêutico.","C":"retirar o DIU de cobre e prescrever metronidazol oral. As parcerias sexuais devem ser tratadas com o mesmo esquema terapêutico.","D":"manter o DIU de cobre e prescrever clindamicina via oral. As parcerias sexuais não devem ser tratadas.","E":"retirar o DIU de cobre e prescrever nistatina via vaginal. As parcerias sexuais devem ser tratadas com o mesmo esquema terapêutico."},"answer":"C","assunto":"Infecções em ginecologia","topico":"Vulvovaginites","subtopico":"Tricomoníase"},{"id":"uepa-2025-074","number":74,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"O câncer de mama é o tipo que mais acomete as mulheres no Brasil. Para identificação de sinais e sintomas suspeitos, o Ministério da Saúde recomenda que os seguintes sinais e sintomas sejam considerados como de referência urgente para serviços de diagnóstico mamário:","options":{"A":"qualquer nódulo mamário em mulheres com mais de 30 anos.","B":"lesão eczematosa da pele que responde a tratamentos tópicos.","C":"nódulo mamário em mulheres com mais de 30 anos, que persistem por mais de um ciclo menstrual.","D":"presença de linfadenopatia submandibular.","E":"mamas de médio volume e pendulares."},"answer":"C","assunto":"Mastologia","topico":"Câncer de mama","subtopico":"Quadro clínico"},{"id":"uepa-2025-075","number":75,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Primigesta, no decorrer da sétima semana de gestação, vem a consulta com queixa de surgimento de lesões eritemato-papulosas de um a três milímetros de diâmetro, que rapidamente evoluiram para vesículas sobre base eritematosa, muito dolorosas e de localização variável na região genital. Nega quadro semelhante anterior. Diante do exposto a conduta adequada é:","options":{"A":"após tratamento antiviral imediato, realizar terapia supressiva, a partir da 36ª semana.","B":"prescrever azitromicina e manter profilaxia até parto.","C":"prescrever doxiciclina e tratar as parcerias sexuais.","D":"prescrever aciclovir 200mg, 2 comprimidos, 8/8h por 5 dias.","E":"o tratamento deve ser postergado para o segundo ou terceiro trimestre."},"answer":"A","assunto":"Doenças associadas à gestação","topico":"Doenças infecciosas na gestação – HIV, sífilis, hepatites, herpes","subtopico":"Herpes na gestação "},{"id":"uepa-2025-076","number":76,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 18 anos de idade, nuligesta, vem a consulta com queixa de nunca ter menstruado e dispareunia importante em primeira relação sexual que ocorreu há 10 dias. Ao exame físico, constata-se o desenvolvimento dos caracteres sexuais secundários em estágio normal para sexo e idade, vulva com formação normal vagina curta. O cariótipo é 46XX, e os exames de imagem da pelve confirmam a presença dos ovários normais e útero ausente. O diagnóstico para o caso é:","options":{"A":"Síndrome dos ovários policísticos.","B":"Síndrome de Morris.","C":"Síndrome de Sheehan.","D":"Síndrome de Mayer-Rokitansky-Kuster-Hauser.","E":"Síndrome de Swyer."},"answer":"D","assunto":"Ginecologia endócrina","topico":"Amenorreias","subtopico":"Amenorreia primária"},{"id":"uepa-2025-077","number":77,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A hiperglicemia na gestação está associada ao risco de diversos desfechos adversos maternos e fetais. É importante destacar que os riscos associados ao diabetes na gestação podem ser reduzidos com o planejamento adequado da gestação e a otimização do controle glicêmico ao longo de todo o período gravídico. Assinale as possíveis complicações decorrentes do diabetes gestacional.","options":{"A":"Candidíase vulvovaginal materna na gestação e hipercalcemia fetal perinatal.","B":"Infecção urinária materna na gestação e hipertensão arterial sistêmica futura na prole.","C":"Doença hipertensiva materna na gestação e gestação prolongada.","D":"Oligoâmnio e risco aumentado para desenvolver obesidade futura na prole.","E":"Proteção contra Desordens hipertensivas da gravidez e risco de óbito fetal."},"answer":"B","assunto":"Doenças associadas à gestação","topico":"Diabetes na gestação (DMG)","subtopico":"Repercussões do diabetes na gestação"},{"id":"uepa-2025-078","number":78,"area":"Obstetrícia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A hemorragia pós-parto é uma das principais causas de mortalidade e morbidade materna no mundo. As medidas de prevenção da HPP devem ser incorporadas na rotina de todos os profissionais que assistem pacientes em trabalho de parto. Durante o manejo ativo do 3º período do trabalho de parto a conduta correta é:","options":{"A":"realizar tração controlada do cordão umbilical clampeado concomitantemente a manobra de Brandt-Andrews.","B":"realizar clampeamento tardio dos vasos umbilicais em recém-nascidos de alto risco para Policitemia.","C":"ocitocina não deve ser utilizada rotineiramente pós-parto.","D":"clampeamento precoce universal.","E":"indicar heparina profilática pós parto."},"answer":"A","assunto":"Parto","topico":"Assistência ao parto normal ","subtopico":"Terceiro periodo: dequitação "},{"id":"uepa-2025-079","number":79,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 35 anos de idade, com queixa de sangramento uterino aumentado de fluxo e duração durante as menstruações há 12 meses, vem a consulta com exame de ultrassonografia transvaginal evidenciando útero antevertido, com presença de lesão nodular característica de leiomioma do útero classificada como FIGO 2. A paciente apresenta desejo de uma gestação futura. A melhor conduta para o caso é:","options":{"A":"miomectomia laparoscópica, pois se trata de um mioma classificado como subseroso.","B":"miomectomia histeroscópica, pois se trata de um mioma FIGO 2.","C":"histerectomia, pois se trata de um mioma transmural.","D":"miomectomia seletiva laparoscópica, pois se trata de um mioma submucoso.","E":"embolização das artérias uterinas, pois se trata de um mioma FIGO 2-5."},"answer":"B","assunto":"Ginecologia geral","topico":"Miomatose uterina","subtopico":"Tratamento"},{"id":"uepa-2025-080","number":80,"area":"Ginecologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 30 anos de idade, com desejo gestacional, apresentando ciclos menstruais irregulares, com presença de acne em dorso e rosto, índice de massa corpórea 30 Kg/m2 , ao exame físico foi observado um escore de 14 na escala de Ferriman-Gallwey, a ultrassonografia transvaginal evidencia ovários de volume igual a 8ml a direita e 5 ml a esquerda, com contagem de 6 folículos. Foram realizados exames que descartam hiperandrogenismo laboratorial, o FSH dosado em primeira fase do ciclo foi de 6,5 mUI/mL, teste de gravidez negativo e função tireoidiana normal. Diante do caso, o diagnóstico e risco futuro para essa paciente são:","options":{"A":"Síndrome dos ovários policísticos, com risco de atrofia endometrial.","B":"Hiperplasia adrenal de manifestação tardia, com risco de insuficiência adrenocortical.","C":"Síndrome de Cushing, com risco de hipopituitarismo.","D":"Síndrome de Stein-Leventhal, com risco aumentado de disfunção ovulatória.","E":"Síndrome de insensibilidade androgênica completa, com risco de câncer de ovário."},"answer":"D","assunto":"Ginecologia endócrina","topico":"Síndrome dos ovários policísticos","subtopico":"Critérios diagnósticos"},{"id":"uepa-2025-081","number":81,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"A vacinação constitui umas das mais importantes estratégias na saúde pública na prevenção de doenças e redução de custos em saúde pública, devendo ser orientada e acompanhada por profissionais de saúde. O Ministério da Saúde oferece uma ampla cobertura vacinal para todas as faixas etárias, através do Programa Nacional de Imunizações. Neste contexto, assinale a alternativa correta.","options":{"A":"Os adolescentes entre 09 a 14 anos devem receber duas doses da vacina HPV Papilomavírus.","B":"A vacina contra Dengue (Qdenga®), inativada, está disponível para indivíduos de 4 a 60 anos de idade, em duas doses.","C":"A primeira dose da vacina Rotavírus humano, atenuada, deve ser administrada no máximo até os 9 meses de idade.","D":"Aos 12 meses a criança deve receber: o reforço da Pneumocócica 10 valente, o reforço da Meningocócica C conjugada e dose única da Febre Amarela.","E":"A vacina Meningocócica ACWY está disponível para adolescentes entre 11 a 14 anos de idade, em dose única."},"answer":"E","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","subtopico":"Calendários vacinais"},{"id":"uepa-2025-082","number":82,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Lactente de 7 meses de vida, em tratamento para otite média aguda com Amoxicilina há 48 horas, é levado ao pronto atendimento durante primeiro episódio convulsivo. Ao chegar na unidade, a crise havia cessado espontaneamente e o paciente encontrava-se sonolento, porém reativo ao manuseio, com temperatura axilar de 38o C. Otoscopia com abaulamento de membrana timpânica direita. Mãe refere histórico de crise febril em irmão mais velho. Assinale a conduta correta em relação ao caso.","options":{"A":"Coletar liquor para afastar infecção de sistema nervoso central.","B":"Administrar diazepam endovenoso e coletar dosagem de eletrólitos, glicemia e culturas.","C":"Acalmar a família, explicando que trata-se de crise febril.","D":"Iniciar tratamento com anticonvulsivante via oral contínuo e encaminhar para a neurologia.","E":"Iniciar aciclovir por tratar-se de possível encefalite viral."},"answer":"A","assunto":"Emergências Pediátricas","topico":"Convulsão febril ","subtopico":"Abordagem da Crise Febril"},{"id":"uepa-2025-083","number":83,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Menino de 5 anos de idade, apresenta lesões violáceas elevadas com predomínio em membros inferiores e nádegas há 2 dias, associadas a dor e edema em tornozelos, mantendo bom estado geral, sem outras alterações. Atendido pelo pediatra que solicitou hemograma e coagulograma, ambos sem alterações. Neste contexto, assinale a alternativa que contém a principal hipótese diagnóstica.","options":{"A":"Púrpura Trombocitopênica Imune (PTI).","B":"Sepsis.","C":"Meningococcemia.","D":"Púrpura de Henoch-Schönlein (vasculite por IgA).","E":"Lúpus Eritematoso sistêmico Juvenil."},"answer":"D","assunto":"Reumatologia Pediátrica","topico":"Púrpura de Henoch-Schöinlein/Vasculite por IgA","subtopico":"Diagnóstico"},{"id":"uepa-2025-084","number":84,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Menina de 12 anos de idade, moradora de Ananindeua-PA, apresenta febre de moderada intensidade há 7 dias, associada a artralgia em joelho direito. Mãe conta que no início do quadro febril, apresentava artralgia em tornozelo que melhorou após 3 dias de evolução. Ao exame físico, regular estado geral e edema em joelho direito, sopro em foco mitral 2/4+, sem outras alterações. Para investigar a principal hipótese diagnóstica, é importante solicitar:","options":{"A":"FAN","B":"Anti Sm","C":"ASLO","D":"Mielograma","E":"Hemograma e hemocultura."},"answer":"C","assunto":"Reumatologia Pediátrica","topico":"Febre Reumática (FR)","subtopico":"Evidência de estreptococcia prévia"},{"id":"uepa-2025-085","number":85,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Dona Ana, 22 anos de idade, dá entrada na unidade materno-infantil em trabalho de parto com 38 semanas de idade gestacional. Relata perda de líquido há 16 horas, realizou 3 consultas de pré-natal, apenas uma no último trimestre. Três horas após a internação deu a luz a recém nascido pesando 2.800 g, APGAR 6/9. O RN evoluiu com desconforto respiratório no alojamento conjunto, 12 horas após o nascimento com gemência, batimento de asa de nariz e tiragem subcostal, com queda de saturação. A alternativa que contém a conduta inicial mais adequada é:","options":{"A":"suporte ventilatório, suporte hídrico e nutricional, bicarbonato de sódio e antibioticoterapia com Ampicilina e Aminoglicosídeo.","B":"suporte ventilatório, suporte hídrico e nutricional, bicarbonato de sódio e antibioticoterapia com Ceftriaxona.","C":"suporte ventilatório, suporte hídrico e nutricional, e antibioticoterapia com Penicilina Cristalina e Aminoglicosídeo.","D":"oxigênio circulatório, coletar exames de rotina e observar o desconforto respiratório durante as próximas 2 horas.","E":"suporte de oxigênio, dieta zero, hidratação venosa e uma dose de penicilina G Benzatina até que sejam avaliados exames complementares."},"answer":"C","assunto":"Neonatologia","topico":"Sepse neonatal","subtopico":"Tratamento"},{"id":"uepa-2025-086","number":86,"area":"Dermatologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Paciente de 2 anos de idade é levado em consulta por apresentar prurido cutâneo há 10 dias, que piora a noite. Ao exame, lesões papulares, algumas com túnel, marcas de escoriação, em mãos, punhos, abdômen e região axilar bilateral. Peso 10 Kg. Sobre o caso descrito o tratamento correto para a principal hipótese diagnóstica é:","options":{"A":"Permetrina loção a 5% em toda superfície corporal, do pescoço para baixo.","B":"Hidroxizina xarope a cada 6 horas.","C":"Ivermectina 200 mcg/kg/dia, repetir após 7 dias.","D":"Corticoide tópico associado a anti-histamínicos de segunda geração.","E":"Anti-histamínico de segunda geração associado a prednisolona por 5 dias."},"answer":null,"assunto":"Dermatoses infecciosas","topico":"Doenças parasitárias","annulled":true},{"id":"uepa-2025-087","number":87,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Mãe leva seu filho de 11 meses de idade à UPA devido desconforto respiratório súbito. Nega coriza, espirros ou febre. Relata ter deixado a criança brincando com os irmãos mais velhos enquanto preparava o jantar e quando retornou o filho apresentada respiração ruidosa e tosse. Ao exame, lactente alerta, agitado, com retração de fúrcula e estridor. Neste momento, a conduta mais adequada é:","options":{"A":"realizar laringoscopia direta.","B":"máscara laríngea.","C":"Dexametasona 0,6 mg/Kg em dose única e adrenalina inalatória.","D":"Rx de tórax e oxigênio inalatório.","E":"realizar 5 compressões entre as escápulas seguidas de 5 compressões torácicas."},"answer":"E","assunto":"Emergências Pediátricas","topico":"Corpo Estranho/Engasgo","subtopico":"Tratamento"},{"id":"uepa-2025-088","number":88,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Criança de 2 anos de idade, previamente hígida, apresenta inapetência e dor abdominal há 48 horas. Mãe relata urina fétida. A criança ainda não apresenta controle esficteriano. Exame físico durante atendimento na UPA, sem alterações. Neste caso, o médico deve:","options":{"A":"Orientar uso de antitérmicos e reavaliação em 48 horas.","B":"Solicitar coleta de exames, incluindo urina rotina e urocultura coletadas via saco coletor.","C":"Iniciar antibioticoterapia empírica para tratamento de cistite, durante 3 dias.","D":"Fazer coleta invasiva de exame de urina para triagem de infecção do trato urinário.","E":"solicitar exame de urina rotina por saco coletor e, se alterada, recoletar via coleta invasiva incluindo urocultura."},"answer":"E","assunto":"Nefrologia Pediátrica ","topico":"Infecção de Trato Urinário (ITU)","subtopico":"Diagnóstico laboratorial"},{"id":"uepa-2025-089","number":89,"area":"Infectologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Criança de 10 anos de idade é atendida em consulta de rotina com queixa de distensão abdominal, flatulência e diarreia volumosa frequente, com restos alimentares, sem muco ou sangue, há 4 meses. Pensando em tratar a etiologia parasitária mais provável, o médico deve prescrever:","options":{"A":"Albendazol durante 5 dias.","B":"Metronidazol durante 10 dias.","C":"Mebendazol durante 3 dias.","D":"Albendazol durante 3 dias.","E":"Praziquantel em dose única."},"answer":"A","assunto":"Parasitoses","topico":"Giardíase"},{"id":"uepa-2025-090","number":90,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Lactente de 3 meses de idade, nascido a termo e com peso adequado para a idade, interna com quadro de coriza hialina há 3 dias e desconforto respiratório há 2 dias. Examinado pelo médico que observou bom estado geral, presença de tiragem subcostal, intercostal, frequência respiratória de 59 irpm, com saturação de O2 95% em ar ambiente. Presença de sibilos difusos. Mãe nega episódios prévios de sibilância. Nesse contexto, assinale a alternativa correta.","options":{"A":"A conduta correta neste caso é internação hospitalar para corticoterapia e boncodilatador oral.","B":"O lactente não apresenta sinais de gravidade, devendo ser acompanhado via ambulatorial e reavaliado em 24 horas.","C":"Há critérios de internação para tratamento com penicilina cristalina via parenteral e broncodilatador inalatório.","D":"O uso de amoxicilina está indicado, associado a corticoide oral e broncodilatador inalatório.","E":"O lactente deve ser internado para medidas de suporte devido a presença de sinais de gravidade e risco de piora clínica nos próximos dias."},"answer":"E","assunto":"Pneumologia Pediátrica","topico":"Bronquiolite ","subtopico":"Tratamento"},{"id":"uepa-2025-091","number":91,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"São direitos dos adolescentes, EXCETO:","options":{"A":"receber informações sobre qualquer aspecto relacionado à sexualidade e saúde reprodutiva além das imunizações comtempladas pelo MS, apenas na presença do responsável legal.","B":"escolha de realizar consulta médica, procedimentos não invasivos como coleta de exames laboratoriais, sozinhos ou acompanhados por familiares, amigos ou parceiros, desde que o profissional reconheça que ele tem discernimento adequado de sua saúde e compreensão de seu autocuidado.","C":"orientados por profissionais de saúde, inclusive por pediatra, podem e devem decidir pela escolha de métodos contraceptivos adequados para essa fase, para o exercício de uma vida sexual saudável e responsável: preservativos masculino e feminino, anticoncepcionais hormonais orais, anticoncepcional injetável, anticoncepcionais de longa duração e ou diafragma, DIU e, se necessária, a contracepção de emergência.","D":"testagem e entrega de exames anti-HIV - até os 12 anos recomenda-se que estes procedimentos ocorram com conhecimento e/ou presença dos pais ou responsáveis.","E":"devem ser atendidos em toda a rede, pública ou privada, sem discriminação de gênero, raça, classe social."},"answer":"A","assunto":"Puericultura ","topico":"Hebiatria","subtopico":"Sexualidade no adolescente"},{"id":"uepa-2025-092","number":92,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Quanto a correlação do aleitamento materno e alergias, é correto afirmar que:","options":{"A":"o aleitamento materno não possui efeito protetor para eczemas, asma e rinite alérgica.","B":"são evidenciados níveis séricos mais elevados de IgE em crianças amamentadas exclusivamente ou parcialmente durante seis meses, o que sugere menor sensibilização a alérgenos alimentares na primeira infância e um papel de prevenção contra alergias no início da vida.","C":"apenas 0,5% a 1% dos bebês exclusivamente amamentados desenvolverão alergia às proteínas do leite de vaca mais tarde em virtude da amamentação proporcionar uma exposição contínua de antígenos ao sistema imunológico materno, durante os primeiros meses de vida, quando o sistema imunitário do bebê está em constante desenvolvimento.","D":"a exposição a pequenas quantidades de leite de vaca durante os primeiros dias de vida não aumenta o risco de alergia ao leite de vaca.","E":"o leite materno não possui correlação com a modulação do sistema imunológico da criança, por componentes bioativos que atuam na imunidade humoral e celular e auxiliam nos mecanismos de maturação imune."},"answer":"C","assunto":"Gastrologia Pediátrica","topico":"Alergia alimentar","subtopico":"Fatores de risco"},{"id":"uepa-2025-093","number":93,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Leia as afirmativas abaixo e assinale a alternativa correta: I. O leite materno pode ser considerado um “tecido vivo”, sendo por isso impossível comparar a sua composição com qualquer outro leite ou alimento. II. A alimentação complementar é definida como o processo de introdução de alimentos, além do leite materno, para os lactentes. Seu início se dá por volta de seis meses e continua até os 23 meses de idade, devendo a amamentação continuar durante esse período. III. Por volta dos seis meses de vida deve-se oferecer a primeira refeição principal (almoço ou jantar) e um lanche na forma de fruta in natura. IV. O consumo de alimentos ultraprocessados, açúcar e doces não é indicado nos dois primeiros anos de vida. V. Os alimentos devem ser cozidos e passados na peneira antes de ser ofertado ao bebe. A alternativa que contém todas as afirmativas corretas é:","options":{"A":"I,II, III, IV e V","B":"I, III e V","C":"II e IV","D":"I, II, III e IV","E":"II, III, IV e V"},"answer":"D","assunto":"Puericultura ","topico":"Alimentação Infantil ","subtopico":"Alimentação do lactente"},{"id":"uepa-2025-094","number":94,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Quanto a Insuficiência Cardíaca (IC) em pediatria, todas estão corretas, EXCETO:","options":{"A":"as principais causas de IC na criança são as cardiopatias congênitas estruturais e as cardiomiopatias, sendo que o grupo das cardiopatias congênitas é a causa mais frequente chegando a ser responsável por 50% a 70% dos casos de IC na infância.","B":"as cardiomiopatias são responsáveis por 20% a 30% de todos os casos de IC na criança, podendo ser de origem primária ou secundária.","C":"sintomas de IC na criança independem da causa , gênero ou idade.","D":"para tratamento adequado de IC na infância, devemos dividi-los em dois grandes grupos : pacientes com sinais de congestão ou pacientes com sinais de baixo debito para melhor orientação de tratamento.","E":"fenômenos tromboembólicos são frequentes em crianças que apresentam IC decorrente de miocardiopatias com disfunção ventricular. Na presença de trombo intracardíaco está indicada a anticoagulação com heparina na fase aguda e posteriormente varfarina. Quando a fração de ejeção de ventrículo esquerdo for menor que 25%, a anticoagulação profilática com heparina ou varfarina também deve ser considerada."},"answer":"C","assunto":"Cardiologia Pediátrica","topico":"Cardiopediatria e Cardiopatias congênitas","subtopico":"Síndromes clínicas da cardiopediatria"},{"id":"uepa-2025-095","number":95,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Recém nascido com 7 dias de vida, retorna em ambulatório com relato de cansaço as mamadas. No exame físico observa-se desconforto respiratório, tiragem inter e subcostal, palidez, pulsos femorais ausentes, perfusão periférica diminuída, taquicardia e hepatomegalia. Observa-se ainda pressão aumentada em membros superiores quando comparado a aferição em membros inferiores. • ECG: hipertrofia do VD com ÂQRS desviado para direita. • Radiografia do tórax: cardiomegalia e congestão venosa pulmonar estão presentes. Ante o exposto o diagnostico provável, é:","options":{"A":"Persistência de canal arterial","B":"Transposição de grandes artérias","C":"CIV","D":"CIA","E":"Coarctação da aorta"},"answer":"E","assunto":"Cardiologia Pediátrica","topico":"Cardiopediatria e Cardiopatias congênitas","subtopico":"Cardiopatias congênitas"},{"id":"uepa-2025-096","number":96,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Quanto a Obesidade infantil, analise as afirmativas abaixo. I. A obesidade infantil já é considerada uma pandemia. II. A obesidade é causada pela interação de fatores genéticos, ambientais e comportamentais. III. O tempo gasto com telas de dispositivos eletrônicos (televisão, smartphone, tablete, videogame, computador) pode contribuir para obesidade infantil. IV. Crianças que não dormem o suficiente podem ter dificuldades em várias áreas, inclusive no desenvolvimento de maus hábitos alimentares. V. Como medida preventiva, cabe as sociedades médicas atualizar os associados com programas de educação continuada sobre prevenção e tratamento da obesidade. A alternativa que contém todas as afirmativas corretas é:","options":{"A":"I, II, IV e V","B":"II, III, IV e V","C":"II, III e IV","D":"I, II, III,IV e V","E":"I, III, IV e V"},"answer":"D","assunto":"Puericultura ","topico":"Diagnóstico Nutricional ","subtopico":"Obesidade"},{"id":"uepa-2025-097","number":97,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Maria, 10 anos de idade, com história de febre há 5 dias, evoluindo há 24 horas com piora clínica, dispneia, do ventilatório dependente, sonolência, tosse produtiva. Ao exame físico: sonolenta, pálida, dispneica, hidratada, tiragem sub e intercostal AP: crepitações em hemitórax direito FR: 30 ipm SO2: 90% em ar ambiente Fc: 165 bpm, ritmo sinusal Pulsos periféricos finos Pcp: 4 segundos PA: 80x40 mmhg Ecg: 10 Ante o exposto, o possível diagnóstico do quadro que a trouxe a urgência é:","options":{"A":"Pneumonia","B":"Choque cardiogênico","C":"Sepse","D":"Choque séptico","E":"Abcesso pulmonar"},"answer":"C","assunto":"Emergências Pediátricas","topico":"Choque em Pediatria","subtopico":"Diagnóstico"},{"id":"uepa-2025-098","number":98,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"Quanto a constipação intestinal na população pediátrica é correta afirmar que:","options":{"A":"não há variação de frequência de evacuações com a idade.","B":"a constipação é um diagnóstico, não devendo ser encarada apenas como um sintoma clinico.","C":"a constipação não tem correlação com tipo de alimentos ou ingestão de líquidos.","D":"fissuras anais, estenose anal e doenças metabólicas devem ser consideradas no diagnostico diferencial.","E":"estudos radiológicos são obrigatórios na constipação intestinal funcional."},"answer":"D","assunto":"Gastrologia Pediátrica","topico":"Constipação","subtopico":"Diagnósticos diferenciais"},{"id":"uepa-2025-099","number":99,"area":"Hematologia","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"João, 5 anos de idade, referindo coriza, mialgia e petéquias em membros inferiores com piora há 24h. ausência de linfadenopatias, visceromegalias ou febre. Hemograma com 10.000 plaquetas, sem outras alterações. Família bem orientada e boa rede de apoio. A melhor conduta a ser tomada, neste caso, é:","options":{"A":"internação e início de corticoterapia.","B":"internação e início de imunoglobulina.","C":"seguimento ambulatorial e reavaliação com hematologista em 24-48 h.","D":"seguimento ambulatorial e início imediato de corticoterapia.","E":"seguimento ambulatorial após dose imediata de imunoglobulina."},"answer":"C","assunto":"Hemostasia","topico":"Hemostasia primária"},{"id":"uepa-2025-100","number":100,"area":"Pediatria","source":"UEPA 2025","examId":"uepa-2025","examName":"UEPA Acesso Direto: 2025","stem":"São causas de hiperbilirrubinemia indireta, exceto:","options":{"A":"hemolise","B":"icterícia pelo leite materno","C":"hipotiroidismo","D":"icterícia fisiológica","E":"atresia de vias biliares"},"answer":"E","assunto":"Neonatologia","topico":"Icterícia nenonatal e distúrbios hematológicos no RN","subtopico":"Icterícia neonatal"}]);
